const top_jax = {
  champion: '잭스',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '1~2레벨에는 (P)\'인내심\' 덕분에 가렌이 체력을 잘 회복하니 (Q)\'도약 공격\'으로 꾸준히 압박을 넣어주세요. 가렌이 (Q)\'결정타\'로 달려들며 침묵을 걸려고 하면 (E)\'반격\'을 아껴두었다가 강화된 평타를 막으며 대응해요. 가렌의 (E)\'심판\'이 빠진 틈에 짧게 교환하고 빠지면서 미니언을 챙기세요.', lv3: '(E)\'반격\'을 켜서 가렌의 (E)\'심판\' 회전 피해를 줄이면서 (Q)\'도약 공격\'으로 진입해 짧게 딜교환을 해요. 가렌이 (W)\'용기\' 보호막을 켜면 무리하게 (W)\'무기 강화\'를 섞지 말고 (E)\'반격\'의 기절을 노리며 빠져 나오세요. 가렌의 (Q)\'결정타\' 침묵에 걸리기 전에 (E)\'반격\'을 먼저 돌리는 판단이 중요해요.', lv6: '가렌의 (R)\'데마시아의 정의\'는 잃은 체력에 비례한 고정 피해라서 (R)\'무기의 달인\'의 방어력과 마법 저항력으로는 줄일 수 없어요. 체력이 낮을 때는 (Q)\'도약 공격\'으로 거리를 벌려 궁극기 사거리에서 벗어나세요. 가렌이 (E)\'심판\'으로 라인을 밀 때 (E)\'반격\'으로 받아치며 정글러의 개입에 대비해요.', item: '첫 코어로 삼위일체를 올리면 (Q)\'도약 공격\'과 평타를 통한 지속 싸움이 훨씬 강력해져요. 신발은 가렌의 평타 피해를 줄여주는 판금 장화를 선택해요. 가렌의 (E)\'심판\' 같은 스킬 피해는 줄이지 못하니 맞지 않도록 위치를 잡으세요.', spell: '점멸과 점화를 추천해요. 점화의 효과로 가렌의 (P)\'인내심\' 회복을 억제해야 (E)\'반격\'을 활용한 교전에서 확실하게 승부를 볼 수 있어요. 가렌의 낮은 체력 타이밍에 점화를 사용하면 승기를 잡기 쉬워요.' },
    '갱플랭크': { lv1: '갱플랭크는 (Q)\'혀어어어업상\'으로 멀리서 골드를 챙기며 견제하니 미니언 사이에서 거리 조절을 잘 해야 해요. 1~2레벨에는 갱플랭크의 (P)\'불의 심판\' 불이 붙은 평타를 조심하며 (Q)\'도약 공격\'으로 진입해 짧게 딜교환을 하세요. 너무 오래 머무르면 갱플랭크의 견제에 체력이 많이 빠질 수 있어요.', lv3: '갱플랭크의 (E)\'화약통\'이 근처에 깔려 있다면 통이 터지는 범위 밖에서 (Q)\'도약 공격\'으로 진입하며 딜교환을 시작하세요. (E)\'반격\'은 통 폭발 같은 광역 피해를 줄이는 용도로만 기대하고, 둔화는 막지 못해요. 갱플랭크가 (W)\'괴혈병 치료\'로 군중 제어를 풀고 체력을 회복할 수 있으니 이 스킬이 빠진 것을 확인한 뒤 (W)\'무기 강화\'를 섞은 공격으로 몰아붙이세요.', lv6: '갱플랭크의 (R)\'포탄 세례\'가 깔린 구역은 이동 속도가 느려지니 그 지역을 피해서 싸우는 것이 중요해요. 갱플랭크가 (W)\'괴혈병 치료\'를 사용하지 못하는 타이밍에 (R)\'무기의 달인\'을 켜고 (Q)\'도약 공격\'으로 진입하면 킬을 낼 수 있어요. 라인을 밀어 넣고 갱플랭크가 (Q)\'혀어어어업상\'으로 골드를 못 챙기게 압박하며 정글러의 지원을 유도하세요.', item: '첫 코어로 삼위일체를 올려 공격력과 체력을 동시에 챙기며 전투력을 높이세요. 신발은 갱플랭크의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 갱플랭크가 (W)\'괴혈병 치료\'로 버티지 못하게 점화로 체력 회복 효과를 줄이면 킬을 따기 쉬워요.' },
    '그라가스': { lv1: '그라가스는 (Q)\'술통 굴리기\'로 둔화를 걸며 견제하고 (P)\'서비스 시간\'으로 체력을 회복해요. 술통의 폭발 위치를 피하며 막타를 챙기고, 거리 조절을 통해 (W)\'무기 강화\'를 섞은 평타 교환을 시도하세요. 초반에는 무리하게 진입하기보다 술통이 빠진 타이밍을 노리는 게 좋아요.', lv3: '(E)\'몸통 박치기\'는 적을 공중으로 띄워 올리니 이 스킬이 빠진 것을 확인하고 (Q)\'도약 공격\'으로 진입하세요. (W)\'취중 분노\'의 강화 평타는 (E)\'반격\'으로 회피하여 상대의 주요 딜교 수단을 무력화하는 것이 중요해요. (E)\'반격\'의 기절 이후 (W)\'무기 강화\'를 적중시키면 짧고 강한 딜교환이 가능해요.', lv6: '(R)\'술통 폭발\'은 적을 폭발 지점에서 멀리 밀어내니 맞은 뒤 거리가 벌어질 것을 감안해 위치를 잡으세요. (E)\'몸통 박치기\'가 빠진 것을 확인한 뒤 (Q)\'도약 공격\'으로 진입하고 (E)\'반격\'의 기절을 넣으세요. (R)\'무기의 달인\'으로 마법 저항력을 올려 그라가스의 마법 피해를 버티며 정글러의 개입에 대비하세요.', item: '삼위일체로 공격력과 체력을 챙겨 지속 교전 능력을 높이세요. 신발은 마법 저항력을 제공하고 (E)\'몸통 박치기\' 외의 군중 제어 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (P)\'서비스 시간\'을 통한 그라가스의 체력 회복을 점화로 억제해야 킬각을 잡기 편해요.' },
    '그웬': { lv1: '1~2레벨에는 그웬이 (P)\'가위 난도질\'로 체력 비례 마법 피해를 넣고 회복하니 평타 교환을 길게 가져가지 마세요. (Q)\'도약 공격\'으로 무리하게 진입하기보다 미니언을 챙기며 그웬의 (Q)\'싹둑싹둑!\' 사거리 밖에서 거리를 유지해요. (E)\'반격\'으로 그웬의 기본 공격을 흘리며 짧게 교환하고 빠지는 것이 좋아요.', lv3: '그웬이 (W)\'신성한 안개\'를 사용하면 안개 밖에서는 그웬을 대상으로 지정할 수 없으니 주의하세요. (E)\'반격\'을 켜고 그웬의 (E)\'돌격가위\' 진입에 맞춰 (Q)\'도약 공격\'으로 붙으며 딜교환을 시도해요. 그웬의 (W)\'신성한 안개\'가 끝나거나 안개 밖으로 나올 때 (W)\'무기 강화\'가 묻은 평타를 넣어 피해를 주세요.', lv6: '그웬이 (R)\'바느질\'로 둔화를 걸며 거리를 벌리려 하면 (Q)\'도약 공격\'으로 빠르게 추격하세요. (R)\'무기의 달인\'을 사용해 마법 저항력을 높인 상태에서 싸워야 그웬의 강력한 마법 피해를 견딜 수 있어요. (E)\'반격\'으로 (Q)\'싹둑싹둑!\'의 범위 피해를 줄이는 타이밍을 잡고 정글러를 불러서 킬각을 보세요.', item: '헤르메스의 발걸음과 삼위일체를 추천해요. 그웬의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 사고, 삼위일체로 전투 능력을 높여야 해요.', spell: '점멸과 점화를 추천해요. 그웬은 패시브로 체력을 회복하니 점화로 그 회복 효과를 줄여야 해요.' },
    '나르': { lv1: '나르는 (Q)\'부메랑 던지기\'로 둔화를 걸며 멀리서 견제하니 부메랑 궤적을 피하며 거리를 조절하세요. 1~2레벨에는 무리하게 들어가기보다 (W)\'무기 강화\'를 켜고 짧게 딜교환하며 체력을 보존하는 것이 좋아요. 나르가 부메랑을 받으면 재사용 대기시간이 줄어드니 부메랑이 돌아오는 타이밍에 주의하세요.', lv3: '나르가 (E)\'폴짝\'으로 들어오면 착지 지점에서 벗어나 거리를 잡고, (E)\'반격\'은 (W)\'슝슝\' 추가 피해가 붙은 평타를 흘리는 용도로 쓰세요. (Q)\'부메랑 던지기\'가 빠진 틈에 (Q)\'도약 공격\'으로 붙어 짧게 딜교환하고 빠지세요. 분노가 차서 메가 나르로 변하기 전에 압박을 마무리하세요.', lv6: '메가 나르가 (R)\'나르!\'로 던질 때 벽에 부딪히면 기절하니 벽 근처에서는 거리를 두며 조심하세요. (R)\'무기의 달인\'을 사용해 방어력을 높이며 메가 나르의 공격을 버티고, 변신이 풀린 상태에서 (Q)\'도약 공격\'으로 진입해 킬각을 보세요. 나르가 메가 나르 상태일 때는 무리하게 싸우지 말고 라인을 관리하며 정글러의 합류를 기다리세요.', item: '삼위일체로 공격력과 공격 속도를 챙겨 전투력을 높이세요. 신발은 나르의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 나르의 체력을 낮추고 마무리 피해를 입히는 것이 효과적이에요.' },
    '나서스': { lv1: '나서스가 (Q)\'흡수의 일격\'으로 미니언 막타를 챙기며 성장하지 못하게 초반부터 강하게 압박하세요. 나서스가 막타를 치려 할 때 (Q)\'도약 공격\'으로 진입하여 짧은 딜교환을 반복하는 것이 좋아요.', lv3: '나서스가 (W)\'쇠약\'을 사용하여 공격 속도를 낮추려 하면 무리하게 싸우지 말고 거리를 조절하세요. 나서스의 (Q)\'흡수의 일격\'을 (E)\'반격\'으로 회피하며 딜교환을 하면 이득을 볼 수 있어요. (E)\'영혼의 불길\' 장판 위에서는 방어력이 깎이니 빠르게 벗어나세요.', lv6: '나서스가 (R)\'사막의 분노\'를 사용해 체력과 공격 범위가 늘어나면 폭풍 안에서 싸우는 것을 피하세요. 나서스의 체력이 낮을 때 (Q)\'도약 공격\'과 (R)\'무기의 달인\'을 활용해 빠르게 몰아붙여 킬을 노리세요. 라인을 꾸준히 밀어 넣어야 나서스가 (Q)\'흡수의 일격\'으로 스택을 쌓는 것을 방해할 수 있어요.', item: '삼위일체를 첫 코어로 올려 공격력과 체력을 챙기세요. 신발은 나서스의 (Q)\'흡수의 일격\' 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 나서스의 체력 회복을 억제하고 초반 압박을 강화하세요.' },
    '녹턴': { lv1: '녹턴의 (Q)\'황혼의 인도자\'가 남긴 궤적 위에서는 녹턴의 이동 속도가 오르니 거리를 유지하세요. 1~2레벨에는 (Q)\'도약 공격\'을 미니언에 사용하여 미니언을 챙기며 체력을 보존하는 것이 중요해요.', lv3: '녹턴이 (W)\'어둠의 장막\'을 켜면 다음 스킬 하나를 막으니 이때 (Q)\'도약 공격\'이나 (E)\'반격\' 기절을 바로 쓰지 마세요. 장막이 끝난 뒤 (E)\'반격\'을 사용하여 녹턴의 평타를 피하고 기절을 성공시키면 상황을 주도할 수 있어요.', lv6: '녹턴이 (R)\'피해망상\'으로 돌격할 때 (R)\'무기의 달인\'을 사용하여 방어력을 높이며 맞서세요. (E)\'말할 수 없는 공포\'에 연결되면 스킬 사거리 밖으로 벗어나 연결을 끊어야 공포에 빠지지 않아요. 벗어나기 어렵다면 (E)\'반격\'으로 녹턴의 평타를 피하며 버티세요.', item: '판금 장화와 삼위일체를 선택하세요. 녹턴의 기본 공격 피해를 줄이기 위해 판금 장화를 가고 공격력과 체력을 얻기 위해 삼위일체를 올려요.', spell: '점멸과 점화를 추천해요. 녹턴의 (P)\'그림자 칼날\'이 기본 공격으로 체력을 회복시키니 점화의 회복 감소가 도움이 돼요. 점멸은 (E)\'말할 수 없는 공포\' 연결 사거리 밖으로 벗어날 때 써요.' },
    '다리우스': { lv1: '1~2레벨에는 (P)\'과다출혈\' 중첩이 쌓이면 매우 위험하니 짧게 교환하고 빠지세요. 다리우스가 (Q)\'학살\'을 사용할 때 도끼날 끝에 맞지 않도록 안쪽으로 빠르게 파고들어 피해를 줄이고 체력 회복을 방해하세요. (E)\'반격\'으로 평타를 회피하며 상대의 공격 템포를 끊어주는 것이 중요해요.', lv3: '(E)\'포획\'에 끌려가면 연계 공격에 노출되므로 스킬이 빠진 것을 확인한 뒤 (Q)\'도약 공격\'으로 진입하세요. (E)\'반격\'을 켜면 (W)\'마비의 일격\'이 묻은 평타를 피하면서 다리우스를 기절시킬 수 있어요. (W)\'무기 강화\'를 섞은 짧은 공격 후 빠르게 거리를 벌려 중첩 관리를 하세요.', lv6: '(R)\'녹서스의 단두대\'는 고정 피해라 (R)\'무기의 달인\'의 방어력으로 줄일 수 없고 출혈 중첩이 높을수록 아파요. 중첩이 다 쌓이기 전에 교전을 마무리하거나 빠지세요. 정글러를 부를 때는 (E)\'포획\'이 빠진 상태에서 호응해야 확실하게 킬을 낼 수 있어요.', item: '삼위일체로 공격력과 공격 속도 그리고 체력을 보강해 지속 교전 능력을 높이세요. 신발은 다리우스의 강력한 평타 피해를 줄여주는 판금 장화가 효율적이에요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'학살\'의 체력 회복 효과를 억제하고 부족한 마무리 피해를 채워 킬을 내세요.' },
    '라이즈': { lv1: '라이즈는 (Q)\'과부하\'를 사용하여 멀리서 견제하려 하니 미니언 뒤에서 피해를 최소화하세요. 1~2레벨에는 라이즈의 마나 소모가 크므로 무리하게 들어가기보다 CS를 챙기며 기회를 보세요. (Q)\'도약 공격\'으로 접근하기 전에 라이즈의 스킬 사거리를 계속 신경 써야 해요.', lv3: '라이즈가 (E)\'주문 전이\'를 맞힌 뒤 (W)\'룬 감옥\'으로 속박하면 (Q)\'도약 공격\'을 쓸 수 없으니 표식이 남은 채 (W)\'룬 감옥\' 사거리에 머물지 마세요. (W)\'룬 감옥\'이 빠진 타이밍에 (Q)\'도약 공격\'으로 파고들어 딜교환을 시작하세요. (E)\'반격\'은 라이즈의 스킬 광역 피해를 줄이는 용도로만 기대하세요.', lv6: '라이즈가 (R)\'공간 왜곡\'을 사용하여 도망가거나 합류할 수 있으니 라인 관리에 주의하세요. (R)\'무기의 달인\'을 켜서 마법 저항력을 높인 상태로 (Q)\'도약 공격\'을 통해 라이즈를 추격하며 킬각을 잡으세요. 라이즈의 속박 연계에 걸리지 않도록 거리 조절을 잘하는 것이 중요해요.', item: '삼위일체와 헤르메스의 발걸음을 추천해요. 삼위일체로 전투 지속력을 높이고 헤르메스의 발걸음으로 마법 저항력과 강인함을 챙기세요.', spell: '점멸과 점화를 추천해요. 라이즈의 거리를 좁히고 체력이 낮은 라이즈를 빠르게 제압하기 좋아요.' },
    '럼블': { lv1: '럼블은 (Q)\'화염방사기\'로 강력한 견제를 하며 압박해요. (P)\'고철장 거인\' 효과로 과열되어 스킬을 못 쓰는 타이밍에 (W)\'무기 강화\'를 켜고 짧게 딜교하세요. 무리하게 붙으면 (E)\'전기 작살\'에 맞고 느려지니 거리 조절이 중요해요.', lv3: '럼블의 (E)\'전기 작살\'을 피하거나 맞은 직후 (Q)\'도약 공격\'으로 빠르게 붙으세요. (E)\'반격\'을 켜서 (Q)\'화염방사기\'의 피해를 줄이고, 럼블이 (W)\'고철 방패\'를 켜기 전에 스턴을 맞히는 게 핵심이에요. (W)\'무기 강화\'를 섞은 평타 공격으로 빠르게 체력을 깎고 빠지세요.', lv6: '(R)\'이퀄라이저 미사일\'의 화염 궤적 위에 서 있으면 피해가 크니 즉시 범위 밖으로 벗어나세요. (R)\'무기의 달인\'을 사용해 마법 저항력을 높이면 럼블의 화력을 버티며 역습할 수 있어요. 럼블이 궁극기를 헛방 쳤을 때가 킬각이니 정글러 호출 시 함께 진입하세요.', item: '삼위일체와 헤르메스의 발걸음을 추천해요. 삼위일체로 공격력과 체력을 챙겨 교전 능력을 높이고, 헤르메스의 발걸음으로 (E)\'전기 작살\'의 둔화 지속시간을 줄이며 마법 피해를 버티세요.', spell: '점멸과 순간이동을 추천해요. 럼블의 (R)\'이퀄라이저 미사일\' 범위에서 빠르게 벗어나거나 라인 복귀와 합류전에서 유용하게 쓰세요.' },
    '레넥톤': { lv1: '레넥톤은 (Q)\'양떼 도륙\'으로 피해를 입히며 체력을 회복하고 분노를 쌓아 초반 교전에 강해요. 1~2레벨에는 (E)\'반격\'을 활용해 레넥톤의 기본 공격을 피하며 버티는 것이 중요해요. 레넥톤이 분노를 쌓아 강화된 (Q)\'양떼 도륙\'을 쓰기 전에 거리를 조절하며 미니언을 챙기세요.', lv3: '레넥톤이 (E)\'자르고 토막내기\'로 진입하며 (W)\'무자비한 포식자\' 기절을 노릴 때 (E)\'반격\'으로 대응하는 것이 핵심이에요. 레넥톤의 (W)\'무자비한 포식자\'가 빠진 뒤에 (Q)\'도약 공격\'으로 들어가 딜교환을 시도하세요. 분노가 높은 레넥톤의 (W)\'무자비한 포식자\'는 기절 시간이 길어지니 주의해야 해요.', lv6: '레넥톤이 (R)\'강신\'을 사용하면 체력이 늘고 분노가 빠르게 차니 정면 승부는 피하는 게 좋아요. (R)\'무기의 달인\'을 켜서 방어력을 높인 뒤 레넥톤의 (R)\'강신\' 지속시간이 끝나기를 기다리세요. 레넥톤이 (E)\'자르고 토막내기\'를 다시 써서 거리를 벌릴 수 있으니 (Q)\'도약 공격\'의 위치 선정이 중요해요.', item: '첫 코어로 삼위일체를 가서 공격력과 스킬 가속을 챙기세요. 신발은 레넥톤의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 레넥톤의 (Q)\'양떼 도륙\'에 의한 체력 회복 효과를 줄여서 킬각을 잡으세요.' },
    '렝가': { lv1: '수풀 근처에 가지 말고 거리 조절을 하며 (W)\'무기 강화\'로 짧게 딜교환을 해요. 상대가 (Q)\'포악함\'을 켜고 진입하면 뒤로 물러나며 피해를 최소화하세요. 첫 웨이브는 무리하게 잡지 말고 경험치만 챙기며 조심스럽게 플레이해요.', lv3: '(E)\'올가미 투척\'은 사거리가 길고 야성이 가득 차면 속박까지 걸리니 투사체 방향에서 벗어나세요. 속박에 걸리면 (Q)\'도약 공격\'을 쓸 수 없으니 야성이 찬 상태에서는 특히 조심해요. (E)\'반격\'은 렝가의 평타를 피하는 용도로 켜고 (W)\'전투의 포효\'로 회복하기 전에 빠르게 피해를 입히세요.', lv6: '상대가 (R)\'사냥의 전율\'로 위장 진입할 때 (R)\'무기의 달인\'을 사용해 방어력을 높이고 반격하세요. 킬각을 잡을 때는 (E)\'반격\'으로 기절시킨 후 빠르게 공격을 퍼부으세요. 라인을 너무 밀면 정글러의 개입에 노출되기 쉬우니 주의하며 관리해요.', item: '판금 장화와 삼위일체를 추천해요. 판금 장화는 기본 공격 피해를 줄여주고 삼위일체는 공격력과 체력 그리고 공격 속도를 모두 제공해요.', spell: '점멸과 점화를 추천해요. 점멸은 필수적인 이동기이며 점화는 (W)\'전투의 포효\'의 회복량을 줄여 킬각을 잡기에 좋아요.' },
    '리븐': { lv1: '리븐은 (Q)\'부러진 날개\'를 사용하여 (P)\'룬 검\'이 충전된 평타로 강력하게 압박해요. 1~2레벨에는 (E)\'반격\'을 활용해 리븐의 평타를 피해내며 성장에 집중하세요. 리븐의 돌진에 바로 반응할 수 있도록 적절한 거리를 유지하며 미니언을 챙겨요.', lv3: '리븐이 (W)\'기 폭발\'로 기절을 시도할 때 (E)\'반격\'을 사용해 피해를 줄이고 반격을 준비하세요. 리븐이 (E)\'용맹\' 보호막을 켜고 들어오면 (W)\'무기 강화\'를 아껴두었다가 보호막이 끝날 때 맞히는 게 좋아요. 리븐의 (Q)\'부러진 날개\' 세 번째 타격에 공중에 뜨지 않도록 주의하며 (Q)\'도약 공격\'으로 거리를 좁히세요.', lv6: '리븐이 (R)\'추방자의 검\'을 활성화하면 사거리가 늘어나니 (R)\'무기의 달인\'으로 방어력을 높여 맞대응하세요. 궁극기를 재사용해 날리는 일격은 스킬 피해라 (E)\'반격\'으로 피할 수 없으니 위험한 거리를 피하세요. 리븐의 체력이 낮을 때는 무리하게 쫓기보다 정글러를 불러 확실히 마무리하세요.', item: '삼위일체를 첫 코어로 선택해 공격력과 스킬 가속을 챙기세요. 신발은 리븐의 물리 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 리븐이 (E)\'용맹\'으로 버티더라도 점화의 피해로 확실하게 킬을 노려보세요.' },
    '리산드라': { lv1: '리산드라는 (Q)\'얼음 파편\'으로 멀리서 둔화를 걸며 견제하니 거리를 조절하며 피해를 줄여야 해요. 1~2레벨에는 리산드라의 스킬이 강한 구간이므로 무리한 (Q)\'도약 공격\' 진입 대신 파밍에 집중하세요.', lv3: '리산드라가 (W)\'서릿발\'로 발을 묶으면 속박 중에는 (Q)\'도약 공격\'을 쓸 수 없으니 (W)\'서릿발\'이 빠진 것을 확인한 뒤 진입하세요. 리산드라의 (E)\'얼음갈퀴 길\' 이동 경로를 예측하며 (E)\'반격\'을 준비하면 효율적인 딜교환을 할 수 있어요.', lv6: '리산드라가 자신에게 (R)\'얼음 무덤\'을 사용하여 무적 상태가 되면 무리하게 공격하지 말고 거리를 두세요. (R)\'무기의 달인\'으로 마법 저항력을 높인 상태에서 무적이 끝나는 순간 (Q)\'도약 공격\'으로 진입하세요.', item: '삼위일체를 첫 코어로 선택해 공격력과 체력을 동시에 챙기세요. 신발은 리산드라의 (W)\'서릿발\' 속박과 (R)\'얼음 무덤\' 기절 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 정화를 추천해요. 리산드라의 (R)\'얼음 무덤\' 기절이나 (W)\'서릿발\' 속박을 정화로 빠르게 풀고 역공할 수 있어요.' },
    '마스터이': { lv1: '마스터 이는 (P)\'2연속 공격\'과 (E)\'우주류 검술\'로 초반 기본 공격이 매우 강해요. 1~2레벨에는 무리하게 싸우기보다 (W)\'무기 강화\'를 활용해 짧게 견제하며 거리를 조절하세요. (Q)\'도약 공격\'은 마스터 이가 다가올 때 대응하는 용도로 아껴두는 것이 좋아요.', lv3: '마스터 이가 (Q)\'일격 필살\'을 사용하면 대상으로 지정할 수 없으니 (Q)\'도약 공격\'을 낭비하지 마세요. 마스터 이가 (W)\'명상\'을 사용해 체력을 회복하고 피해를 줄이는 동안에는 무리하게 딜을 쏟지 말고 기다려야 해요. (E)\'반격\'으로 마스터 이의 기본 공격을 피한 뒤 기절을 맞히면 효과적이에요.', lv6: '마스터 이가 (R)\'최후의 전사\'를 사용하면 이동 속도가 빨라지니 (E)\'반격\'으로 기절을 시키는 것이 중요해요. (R)\'무기의 달인\'을 사용해 방어력과 마법 저항력을 높여 마스터 이의 공격을 견뎌내세요. 마스터 이가 (Q)\'일격 필살\'로 진입하며 킬을 노릴 수 있으니 정글러의 개입에 주의하며 라인을 관리하세요.', item: '삼위일체를 첫 코어로 올려서 전투력을 높이세요. 신발은 마스터 이의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 마스터 이가 (W)\'명상\'으로 체력을 회복하는 것을 점화로 억제해야 해요.' },
    '마오카이': { lv1: '마오카이가 (Q)\'덤불 주먹\'으로 밀어내며 둔화를 걸고 (P)\'마법 흡수\'로 체력을 회복해요. 1~2레벨에는 너무 깊게 들어가지 말고 평타 위주로 딜교환하며 거리를 조절하세요. 상대가 (Q)\'덤불 주먹\'을 헛치게 유도한 뒤에 짧게 공격하고 빠지세요.', lv3: '(W)\'뒤틀린 전진\'은 마오카이를 대상으로 지정할 수 없는 채 돌진해 속박하니 스킬이 빠진 것을 확인한 뒤 (Q)\'도약 공격\'으로 진입하세요. 마오카이의 평타는 (E)\'반격\'으로 피하며 기절을 노려요. (E)\'묘목 던지기\'가 설치된 수풀 주변은 둔화 위험이 크니 피해서 이동하세요.', lv6: '(R)\'대자연의 마수\'의 벽이 다가올 때 옆으로 빠르게 움직여 속박을 피하세요. 벽을 피한 직후 (R)\'무기의 달인\'을 사용해 방어력과 마법 저항력을 높이고 빠르게 공격하세요. 정글러가 (R)\'대자연의 마수\' 벽 뒤에서 합류할 수 있으니 항상 주의하세요.', item: '삼위일체를 가서 공격 속도와 체력을 챙겨 지속 전투력을 높이세요. 신발은 마법 저항력을 높이고 속박과 둔화 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 마오카이의 강력한 CC기 연계를 피하고 라인 복귀를 빠르게 하세요.' },
    '말자하': { lv1: '말자하의 (P)\'공허 태세\'가 켜져 있으면 받는 피해가 줄고 군중 제어에 면역이니, 평타로 먼저 때려 효과를 풀어내세요. (Q)\'공허의 부름\'은 침묵을 걸어 스킬 사용을 막으니, 투사체가 날아오는 길목에서 비켜나야 해요. 1~2레벨에는 말자하의 사거리가 더 길어서 거리 조절을 하며 막타를 챙기세요.', lv3: '(E)\'재앙의 환상\'에 걸리면 지속 피해를 입고 (W)\'공허의 무리\'가 몰려드니, (E)\'반격\'으로 공허충의 공격을 피하며 말자하까지 기절시키세요. (Q)\'공허의 부름\' 침묵에 걸리기 전에 (Q)\'도약 공격\'으로 빠르게 접근해 (W)\'무기 강화\' 피해를 입히는 것이 좋아요. 상대의 (P)\'공허 태세\'가 사라진 순간을 노려 짧고 강하게 딜교환을 하세요.', lv6: '(R)\'황천의 손아귀\'는 제압이라 (E)\'반격\'이나 (R)\'무기의 달인\'을 사용할 수 없으니, 궁극기에 잡히지 않도록 주의하세요. (R)\'무기의 달인\'을 켜면 마법 저항력이 상승해 말자하의 마법 피해를 더 잘 견딜 수 있어요. 말자하가 라인을 밀어내면 포탑 근처에서 대기하다가 (Q)\'도약 공격\'으로 진입해 킬각을 보세요.', item: '삼위일체와 헤르메스의 발걸음을 가세요. 삼위일체로 체력과 공격 속도를 챙겨 빠르게 압박하고, 헤르메스의 발걸음으로 마법 저항력을 높이고 (Q)\'공허의 부름\' 침묵 시간을 줄이세요.', spell: '점멸과 순간이동을 추천해요. 정화로는 (R)\'황천의 손아귀\' 제압을 풀 수 없으니, 운영을 위한 순간이동과 변수 창출을 위한 점멸이 더 효율적이에요.' },
    '말파이트': { lv1: '말파이트는 (Q)\'지진의 파편\'으로 계속 견제하며 이동 속도를 훔치는데, 대상 지정 스킬이라 미니언 뒤에 숨어도 피할 수 없어요. (P)\'화강암 방패\'가 활성화된 상태에서는 평타 교환이 손해이니, 방패가 깨진 것을 확인하고 (W)\'무기 강화\'를 섞은 평타로 짧게 딜교환하세요. 1~2레벨에는 무리하게 붙기보다 피해를 최소화하며 경험치를 챙기는 것이 좋아요.', lv3: '(E)\'지면 강타\'를 맞으면 공격 속도가 감소해서 평타 기반인 잭스가 힘들어지니, 상대의 스킬 사용 타이밍을 잘 보세요. 말파이트가 (W)\'천둥소리\'를 켜고 진입할 때는 (E)\'반격\'을 사용해 기본 공격을 모두 회피하고 기절시키세요. 이후 (Q)\'도약 공격\'으로 빠르게 붙어 (W)\'무기 강화\' 피해를 입히며 딜교환을 마무리하세요.', lv6: '(R)\'멈출 수 없는 힘\'에 맞으면 공중에 떠서 아무것도 못 하니, 정글러가 근처에 있을 때는 돌진 거리 밖에서 대기하세요. 말파이트가 궁극기를 쓴 직후에 (R)\'무기의 달인\'을 켜서 방어력과 마법 저항력을 올리고 빠르게 접근해 공격하세요. 라인을 적당히 당겨두고 상대의 돌진 이후 빈틈을 노려 (Q)\'도약 공격\'으로 진입하는 것이 안전해요.', item: '삼위일체를 가서 공격력과 체력 그리고 공격 속도를 챙겨 방어력이 높은 말파이트를 지속적으로 압박하세요. 신발은 마법 저항력을 높이고 (Q)\'지진의 파편\'의 둔화 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. (Q)\'지진의 파편\'에 둔화되어도 점멸로 위치를 조정해 (R)\'멈출 수 없는 힘\'의 돌진을 피할 수 있어요. 순간이동은 라인을 정리한 뒤 복귀하거나 합류할 때 써요.' },
    '모데카이저': { lv1: '모데카이저는 (Q)\'말살\'을 단일 대상에게 맞히면 피해가 커지니 미니언과 적절히 거리를 두세요. (P)\'암흑 탄생\' 오라가 켜지면 주변 피해가 강해지므로 1~2레벨에는 (Q)\'도약 공격\'을 아끼며 거리를 조절하세요.', lv3: '모데카이저의 (E)\'죽음의 손아귀\'는 범위 안의 적을 끌어당기니 사거리 밖에서 위치를 잡고, 스킬이 빠진 뒤에 (Q)\'도약 공격\'으로 진입하세요. (E)\'반격\'을 사용하여 모데카이저의 기본 공격을 피하고, (W)\'불멸\' 보호막이 쌓였을 때는 무리한 교환을 피하는 것이 좋아요.', lv6: '(R)\'죽음의 세계\'에 끌려가면 수은 장식띠나 순간이동으로 빠져나갈 수 없으니 조심해야 해요. 궁극기 안에서는 (R)\'무기의 달인\'을 사용하여 방어력과 마법 저항력을 높여 버티는 것이 중요해요. 모데카이저의 (E)\'죽음의 손아귀\'가 빠진 뒤에 (Q)\'도약 공격\'으로 진입하세요.', item: '첫 코어로 삼위일체를 가면 공격력과 스킬 가속을 챙길 수 있어 전투에 도움을 줘요. 신발은 모데카이저의 마법 피해를 줄여주는 헤르메스의 발걸음을 선택하세요.', spell: '점멸과 점화를 추천해요. (W)\'불멸\'을 통해 체력을 회복하는 모데카이저를 점화로 억제하며 공격하세요.' },
    '문도박사': { lv1: '문도 박사는 (Q)\'오염된 뼈톱\'으로 현재 체력에 비례한 피해를 주고 둔화를 걸어요. 이 투사체는 처음 맞는 대상에게 적중하니 미니언 뒤에 숨어 피해를 피하세요. (Q)\'도약 공격\'으로 거리를 조절하며 짧게 딜교환을 반복하고, 상대가 통을 주워 회복하는 것을 방해하세요.', lv3: '(W)\'심장 전기 충격\'이 켜져 있을 때는 받는 피해를 저장해 회복하니, 가급적 짧게 치고 빠지세요. 문도가 (E)\'둔기에 의한 외상\'으로 강하게 때리려 할 때 (E)\'반격\'으로 공격을 회피하고 기절시키세요. (W)\'무기 강화\'를 섞어 빠르게 피해를 입히고, 상대의 (P)\'가고 싶은 데로 간다\'가 빠진 것을 확인하고 공격하세요.', lv6: '(R)\'최대 투여량\'을 사용하면 체력이 대폭 회복되고 이동 속도가 빨라지니, 궁극기를 쓰기 전이나 효과가 끝난 뒤를 노리세요. (R)\'무기의 달인\'을 켜서 방어력과 마법 저항력을 높여 (W)\'심장 전기 충격\'의 피해를 버텨내세요. 정글러와 함께 공격할 때는 문도의 (P)\'가고 싶은 데로 간다\'가 준비되어 있으면 첫 기절이나 속박이 막힐 수 있으니 주의하세요.', item: '삼위일체를 첫 코어로 가서 공격력과 체력을 확보하고 처형인의 대검을 섞어 회복량을 줄이세요. 신발은 마법 피해를 줄이고 강인함을 주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 문도 박사는 체력 회복 수단이 매우 많으므로 점화의 치유 감소 효과가 필수적이에요.' },
    '바루스': { lv1: '바루스는 (Q)\'꿰뚫는 화살\'로 멀리서 견제하며 (W)\'역병 화살\'을 평타에 묻히려고 해요. 무리하게 다가가기보다 미니언을 먹으며 거리를 조절하세요. (Q)\'도약 공격\'으로 파고들 타이밍을 노리며 체력을 관리하는 것이 중요해요.', lv3: '바루스가 (E)\'퍼붓는 화살\'로 지면을 오염시켜 둔화를 걸면 그 위에서 싸우지 마세요. (E)\'반격\'을 사용하여 바루스의 평타 피해를 피하면서 (Q)\'도약 공격\'으로 빠르게 접근하세요. 바루스의 (W)\'역병 화살\'이 터지기 전에 (E)\'반격\'의 기절을 맞히는 것이 핵심이에요.', lv6: '바루스의 (R)\'부패의 사슬\'에 맞으면 이동이 제한되니 진입할 때 조심하세요. 만약 맞았다면 (R)\'무기의 달인\'을 사용해 방어력과 마법 저항력을 높이며 버티세요. 바루스가 궁극기를 빗맞히면 (Q)\'도약 공격\'으로 거리를 좁혀서 압박하세요.', item: '삼위일체를 첫 코어로 올려 공격력과 스킬 가속을 확보하세요. 신발은 바루스의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 바루스의 (Q)\'꿰뚫는 화살\' 사거리가 길어 점멸로 조준선에서 벗어나거나 거리를 좁힐 수 있어요. 점화는 체력이 낮아진 바루스를 마무리할 때 써요.' },
    '베인': { lv1: '베인은 (Q)\'구르기\'로 거리를 조절하며 (W)\'은화살\'로 고정 피해를 입혀요. 1~2레벨에는 무리하게 싸우지 말고 미니언을 챙기며 적과 거리를 유지하세요.', lv3: '베인이 (E)\'선고\'를 사용해 벽으로 밀어내지 못하게 벽에서 떨어져서 싸우세요. (E)\'반격\'을 사용하여 베인의 평타를 피하면서 (Q)\'도약 공격\'으로 거리를 좁히는 것이 중요해요.', lv6: '베인이 (R)\'결전의 시간\'을 사용해 투명해지면 (Q)\'도약 공격\'을 맞히기 어려워지니 주의하세요. (R)\'무기의 달인\'으로 방어력을 높인 뒤 베인의 궁극기가 끝난 타이밍에 진입하세요.', item: '삼위일체를 첫 코어로 가세요. 공격력과 공격 속도를 올려줘요. 신발은 베인의 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 베인이 (Q)\'구르기\'를 써서 도망가기 전에 빠르게 접근해 마무리하세요.' },
    '볼리베어': { lv1: '볼리베어는 (Q)\'번개 강타\'를 사용해 빠르게 접근하며 기절을 걸어요. 1~2레벨에는 무리하게 붙지 말고 (E)\'반격\'으로 평타 공격을 회피하며 체력을 보존하세요. (P)\'무자비한 폭풍\'으로 공격 속도가 올라가면 평타 교환에서 밀리니 짧게 치고 빠지세요.', lv3: '(W)\'광란의 상처\' 표식이 남은 상태에서 두 번째 공격을 맞으면 볼리베어가 체력을 회복하니 빠르게 거리를 벌리세요. (E)\'천공 분열\'은 지정한 위치에 번개가 떨어져 둔화를 거니 낙하 범위를 보고 벗어나세요. (Q)\'번개 강타\' 기절이 빠진 틈에 (W)\'무기 강화\'를 섞어 빠르게 타격하세요.', lv6: '(R)\'폭풍을 부르는 자\'로 포탑이 비활성화되면 다이브를 시도할 수 있으니 주의하세요. 볼리베어가 도약한 직후 (R)\'무기의 달인\'을 사용하여 방어력과 마법 저항력을 높이고 맞서 싸우세요. (E)\'반격\'으로 적의 공격을 쳐낸 뒤 기절시키고 (Q)\'도약 공격\'으로 끝까지 추격하세요.', item: '삼위일체를 가서 공격력과 체력을 동시에 챙기세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'광란의 상처\'를 통한 볼리베어의 체력 회복을 억제하세요.' },
    '블라디미르': { lv1: '블라디미르는 (Q)\'수혈\'로 체력을 흡수하며 견제해요. (Q)\'수혈\'은 대상 지정 스킬이라 미니언 뒤에 숨어도 맞으니 무작정 버티지 마세요. (W)\'무기 강화\'를 켜고 짧게 평타를 치고 빠지는 방식으로 체력 차이를 만들어 두세요.', lv3: '블라디미르가 (E)\'선혈의 파도\'를 충전할 때 미니언 뒤에 서서 투사체를 가로막으세요. (W)\'피의 웅덩이\' 상태에서는 대상으로 지정할 수 없으니 웅덩이가 끝난 뒤에 (Q)\'도약 공격\'으로 진입하세요. (E)\'반격\'을 켜서 (E)\'선혈의 파도\' 광역 피해를 줄이고 기절시킨 뒤 공격하세요.', lv6: '(R)\'혈사병\'에 감염되면 받는 피해가 늘어나니 감염된 상태에서는 무리한 진입을 멈추고 빠지세요. 블라디미르의 (W)\'피의 웅덩이\'가 빠진 타이밍에 (R)\'무기의 달인\'을 켜고 빠르게 붙어 강력한 피해를 입히세요. (Q)\'도약 공격\'으로 진입해 스턴을 넣고 킬각을 잡되 정글러의 개입을 유도하며 라인을 관리하세요.', item: '삼위일체와 헤르메스의 발걸음을 추천해요. 삼위일체는 공격력과 체력 그리고 공격 속도를 높여주고 헤르메스의 발걸음은 마법 저항력을 제공하며 (E)\'선혈의 파도\' 둔화 지속시간을 줄여줘요.', spell: '점멸과 점화를 추천해요. 블라디미르가 (Q)\'수혈\'로 회복하는 양을 점화의 치유 감소 효과로 억제해야 처치할 수 있어요.' },
    '뽀삐': { lv1: '뽀삐가 (Q)\'망치 강타\'로 지대를 만들어 둔화시키니 지대를 피해 거리를 유지하세요. 뽀삐가 (P)\'강철의 외교관\'으로 보호막을 얻기 전에 평타와 (W)\'무기 강화\'를 섞어 짧게 교환하는 것이 좋아요. 초반에는 무리하게 들어가기보다 미니언을 챙기며 2레벨을 먼저 노리세요.', lv3: '뽀삐의 (W)\'굳건한 태세\'는 주변에서 돌진하는 적을 막으니 (Q)\'도약 공격\'을 쓰기 전에 뽀삐의 스킬이 빠졌는지 확인하세요. 뽀삐가 (E)\'용감한 돌진\'으로 벽에 밀어붙여 기절시키지 않도록 벽 근처에서는 조심해야 해요. 뽀삐의 (W)\'굳건한 태세\'가 빠진 타이밍에 (E)\'반격\'을 사용하여 딜교환을 하세요.', lv6: '뽀삐가 (R)\'수호자의 심판\'으로 멀리 날려버리면 킬각이 끊길 수 있으니 주의하세요. 잭스가 (R)\'무기의 달인\'을 사용해 방어력과 마법 저항력을 높이면 뽀삐의 공격을 더 잘 버틸 수 있어요. 뽀삐가 궁극기를 사용한 직후에는 딜교환이 수월해지니 적극적으로 압박하세요.', item: '삼위일체를 첫 코어로 가서 공격력과 공격 속도를 챙기세요. 신발은 공격 속도를 올려주는 광전사의 군화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 뽀삐의 체력을 깎으며 킬을 노리세요.' },
    '사이온': { lv1: '(E)\'학살자의 포효\'는 미니언을 밀쳐내며 관통하니 미니언 뒤에 숨기보다 옆으로 피하세요. 사이온이 (Q)\'대량 학살 강타\'를 길게 충전하면 공중에 띄워 기절시키니 충전 방향에서 벗어나세요. 상대 스킬이 빠진 틈에 (W)\'무기 강화\'를 사용해 짧게 딜교환하고 빠지세요.', lv3: '(W)\'영혼의 용광로\'의 보호막이 켜진 동안은 공격을 자제하고 보호막이 터진 뒤에 진입하세요. 사이온이 (Q)\'대량 학살 강타\'를 사용할 때 (E)\'반격\'을 켜면 피해를 줄이고 이후 기절까지 연계할 수 있어요. (E)\'학살자의 포효\'로 방어력이 깎이기 전에 (Q)\'도약 공격\'으로 빠르게 접근해 공격하세요.', lv6: '(R)\'멈출 수 없는 맹공\'은 저지 불가 상태로 돌진하므로 정면에서 맞지 말고 옆으로 비켜서서 피하세요. (R)\'무기의 달인\'을 사용해 방어력을 높인 뒤 (E)\'반격\'으로 적의 공격을 받아내면 킬각을 잡기 편해요. 사이온이 죽은 뒤 (P)\'영광스러운 죽음\' 상태일 때는 무리하게 붙지 말고 거리 조절을 하세요.', item: '몰락한 왕의 검을 첫 코어로 가서 체력이 높은 사이온에게 현재 체력 비례 피해를 넣으세요. 신발은 사이온의 평타 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 사이온은 라인 밀기가 강한 챔피언이라 순간이동으로 빠르게 복귀하는 것이 중요해요.' },
    '사일러스': { lv1: '1~2레벨에는 사일러스가 (Q)\'사슬 후려치기\'로 견제하고 (P)\'페트리사이트 폭발\'로 평타 피해를 더해요. 사슬이 교차하는 지점에서 터지는 추가 피해를 피하며 (W)\'무기 강화\'를 섞은 기본 공격으로 압박하세요. 무리하게 들어가기보다 상대의 스킬 쿨타임을 확인하며 짧게 딜교환하세요.', lv3: '(E)\'억압\' 사슬에 적중해 공중으로 띄워지면 (E)\'반격\'을 쓰기 어려우니 사슬이 날아올 때 옆으로 피하세요. (W)\'국왕시해자\' 돌진 후 회복하기 전에 (W)\'무기 강화\'를 섞은 공격으로 빠르게 피해를 입히세요. 사일러스의 평타 강화 공격은 (E)\'반격\'으로 모두 무시하고 기절시켜 딜교환을 이끄세요.', lv6: '사일러스는 (R)\'강탈\'로 적 챔피언의 궁극기를 훔쳐 쓰니 잭스의 (R)\'무기의 달인\'도 가져갈 수 있어요. (R)\'무기의 달인\'으로 마법 저항력을 높여 사일러스의 마법 피해를 줄이세요. (Q)\'도약 공격\'으로 진입한 뒤 (E)\'반격\'의 광역 기절로 아군의 개입을 도우세요.', item: '맬모셔스의 아귀를 첫 코어로 가서 마법 저항력을 챙기고 생명선 보호막으로 생존력을 높이세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음이 적합해요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'국왕시해자\'의 체력 회복 효과를 감소시켜 킬각을 잡으세요.' },
    '세주아니': { lv1: '(W)\'무기 강화\'를 활용해 짧게 공격하며 세주아니의 체력을 깎으세요. 세주아니가 (W)\'혹한의 서릿발\'로 둔화를 걸며 접근하면 뒤로 물러나며 거리 조절을 해요.', lv3: '세주아니가 (Q)\'혹한의 맹습\'으로 진입하면 공중에 뜨니 돌진 경로를 벗어나 맞기 전에 위치를 잡으세요. (E)\'반격\'은 세주아니의 평타를 피하는 용도로 쓰고, (E)\'만년 서리\' 중첩이 쌓이기 전에 (Q)\'도약 공격\'으로 빠지거나 역공하세요.', lv6: '세주아니의 (R)\'빙하 감옥\'에 맞지 않도록 무빙에 신경 쓰며 딜교환을 해요. (R)\'무기의 달인\'을 켜서 방어력과 마법 저항력을 높인 뒤 (Q)\'도약 공격\'으로 진입해 킬각을 보세요.', item: '헤르메스의 발걸음과 삼위일체를 가요. 강인함으로 세주아니의 기절과 둔화 지속시간을 줄이고 공격력과 체력을 보충해요.', spell: '점멸과 순간이동을 추천해요. 탑 라인은 복귀와 합류가 중요하니 순간이동으로 라인을 지켜요. 점멸은 (Q)\'혹한의 맹습\' 돌진 경로나 (R)\'빙하 감옥\' 사거리에서 벗어날 때 써요.' },
    '세트': { lv1: '세트는 (Q)\'주먹다짐\'으로 이동 속도를 높여 다가오며 평타로 강력한 피해를 줘요. (P)\'투기장의 투지\'로 체력을 회복하니 너무 길게 평타를 교환하지 마세요. (W)\'무기 강화\'를 섞은 짧은 딜교환 후 빠르게 빠져나오세요.', lv3: '세트의 (Q)\'주먹다짐\' 평타는 (E)\'반격\'으로 모두 회피하고 기절시켜 흐름을 끊으세요. 세트가 피해를 많이 입어 투지가 쌓였을 때 사용하는 (W)\'강펀치\'는 고정 피해가 강력하니 중심선에서 벗어나야 해요. (E)\'안면 강타\'의 둔화를 피하며 (Q)\'도약 공격\'으로 빠르게 거리를 조절하세요.', lv6: '세트의 (R)\'대미 장식\'은 제압 효과라 끌려가면 아무것도 할 수 없으니 주의하세요. (R)\'무기의 달인\'을 켜서 방어력과 마법 저항력을 높인 상태에서 (E)\'반격\'으로 세트의 공세를 막아내세요. (R)\'대미 장식\' 이후 세트가 다시 붙을 수단이 없을 때 (Q)\'도약 공격\'으로 추격해 마무리하세요.', item: '삼위일체로 공격 속도와 체력을 챙겨 지속 싸움 능력을 높이세요. 신발은 세트의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 세트가 (P)\'투기장의 투지\'로 회복하는 양을 줄여 마무리하기 쉬워요.' },
    '쉔': { lv1: '쉔은 (Q)\'황혼 강습\'으로 최대 체력 비례 피해를 주고 (P)\'기 보호막\'으로 피해를 흡수해요. 1~2레벨에는 무리하게 붙지 말고 쉔의 보호막이 사라진 뒤에 (Q)\'도약 공격\'으로 진입해 짧게 딜교환하세요. 기의 검에 부딪히면 쉔에게서 멀어질 때 둔화되니 기의 검 경로를 피하세요.', lv3: '쉔이 (W)\'의지의 결계\'를 켜면 기본 공격이 차단되니, 결계가 끝날 때까지 (W)\'무기 강화\'를 아끼며 대기하세요. (E)\'그림자 돌진\'에 맞아 도발되면 스킬을 쓸 수 없으니 돌진이 오기 전에 (E)\'반격\'을 미리 켜두세요. 쉔의 평타는 (E)\'반격\'으로 피하고 기절로 역공하세요.', lv6: '쉔이 (R)\'단결된 의지\'로 아군을 도우러 가면 빠르게 라인을 밀어 포탑을 압박하세요. 쉔과 정면으로 싸울 때는 (R)\'무기의 달인\'을 켜서 방어력과 마법 저항력을 높이고 연속 평타로 피해를 넣으세요. 쉔의 (E)\'그림자 돌진\'이 빠진 상태에서 (Q)\'도약 공격\'으로 들어가면 쉔이 도망치기 어려워 킬각을 잡기 편해요.', item: '삼위일체와 헤르메스의 발걸음을 가세요. 삼위일체로 체력과 공격 속도를 챙기고, 헤르메스의 발걸음으로 (E)\'그림자 돌진\'의 도발 지속 시간을 줄여 대응하세요.', spell: '점멸과 순간이동을 추천해요. 쉔이 (R)\'단결된 의지\'로 다른 라인에 합류할 때 함께 따라가거나 손실을 최소화하며 복귀하세요.' },
    '쉬바나': { lv1: '쉬바나가 (Q)\'잉걸불 일격\'으로 강하게 압박할 수 있으니 거리를 조절하며 파밍에 집중하세요. (E)\'반격\'을 활용해 상대의 공격을 받아내며 미니언을 챙기는 것이 좋아요. 무리한 진입보다는 안정적으로 성장하는 데 집중하세요.', lv3: '(E)\'반격\'을 사용하여 쉬바나의 (Q)\'잉걸불 일격\'이나 기본 공격을 피하며 진입하세요. 상대가 (W)\'지옥불 방패\'로 보호막을 얻기 전에 (Q)\'도약 공격\'과 (W)\'무기 강화\'를 활용해 딜교환을 해요. (E)\'용암 분출\'의 둔화에 걸리지 않도록 주의하며 스킬을 사용하세요.', lv6: '쉬바나가 (R)\'용의 강림\'을 사용해 용으로 변신하면 저지 불가 상태로 달려드니 주의해야 해요. (R)\'무기의 달인\'을 켜서 방어력과 마법 저항력을 높인 뒤 맞서 싸우세요. 상대가 변신했을 때는 무리하게 싸우기보다 라인 관리를 하며 정글의 개입을 기다려요.', item: '삼위일체와 헤르메스의 발걸음을 가세요. 마법 저항력과 강인함을 얻기 위해서예요.', spell: '점멸과 점화. 상대의 체력이 낮을 때 점화로 피해를 입히며 확실하게 킬을 노리기 위해서예요.' },
    '스웨인': { lv1: '스웨인은 (Q)\'죽음의 손길\'로 멀리서 견제하며 (P)\'굶주린 새떼\'로 체력을 채워요. 1~2레벨에는 무리하게 진입하기보다 (Q)\'도약 공격\'을 사용해 짧게 치고 빠지며 체력 차이를 벌리세요. 스웨인이 영혼 조각을 모으기 전인 초반 구간에 이득을 보는 것이 중요해요.', lv3: '(E)\'속박명령\'은 나갔다가 돌아오며 적을 속박하니 파동이 지나가는 방향을 보고 옆으로 비켜서세요. 속박을 피한 뒤에는 (Q)\'도약 공격\'으로 접근해 (E)\'반격\'을 사용하면 스웨인을 기절시키고 교전에서 앞서갈 수 있어요. (W)\'제국의 눈\'에 맞아 둔화가 걸리면 거리가 벌어지니 주의하세요.', lv6: '스웨인이 (R)\'악의 승천\'을 사용하면 주변 적의 체력을 흡수하니 근접해서 너무 오래 머물지 마세요. (R)\'무기의 달인\'을 켜서 방어력과 마법 저항력을 높인 뒤 (E)\'반격\'으로 스웨인의 공격을 피하며 몰아붙이세요. 스웨인이 변신했을 때 정글러와 함께 노리면 킬을 따내기 쉬워요.', item: '마법 저항력을 높여주는 헤르메스의 발걸음과 지속 전투력을 높여주는 삼위일체를 추천해요. 이 조합은 스웨인의 마법 피해를 견디며 강력한 맞대결을 가능하게 해요.', spell: '점멸과 점화를 추천해요. 스웨인이 (R)\'악의 승천\'과 (P)\'굶주린 새떼\'로 체력을 회복하므로 점화로 회복을 억제해야 해요.' },
    '스카너': { lv1: '1~2레벨에는 스카너의 (Q)\'부서진 대지/지반 돌출\'을 활용한 강화 평타를 조심하며 거리를 유지해요. (Q)\'도약 공격\'으로 미니언을 챙기거나 상대의 움직임을 관찰하며 안정적으로 성장하세요. 무리하게 진입하기보다 적절한 거리를 유지하며 파밍에 집중하는 것이 좋아요.', lv3: '3레벨 이후에는 (E)\'반격\'을 사용하여 상대의 기본 공격을 회피하며 딜교환을 시도해요. 스카너가 (W)\'대지의 수호자\'로 보호막을 얻었을 때는 무리하게 들어가지 말고 보호막이 사라진 뒤에 (W)\'무기 강화\'를 섞은 공격을 하세요. (E)\'이쉬탈의 격돌\'이 빠진 상태를 확인하고 진입하면 더 편해요.', lv6: '6레벨 이후에는 스카너의 (R)\'꿰뚫기\'에 제압당하지 않도록 주의하며 거리를 조절해요. (R)\'무기의 달인\'을 사용하여 방어력과 마법 저항력을 높인 뒤 정면 승부를 하세요. 라인을 먼저 밀어 넣은 뒤 상대의 주요 스킬이 빠진 것을 확인하고 (Q)\'도약 공격\'으로 진입해 킬각을 보세요.', item: '판금 장화와 삼위일체를 추천해요. 판금 장화는 상대의 기본 공격 피해를 줄여주고 삼위일체는 공격력과 공격 속도를 제공하여 지속 전투를 도와줘요.', spell: '점멸과 점화. 점멸은 상대의 스킬을 피하거나 순식간에 거리를 좁히는 데 사용하고 점화는 적을 확실히 마무리하기 위해 필요해요.' },
    '신지드': { lv1: '신지드는 (Q)\'맹독의 자취\'로 독구름을 남기니 그 위에서 싸우지 마세요. (Q)\'도약 공격\'으로 접근할 때 독구름에 닿지 않도록 거리 조절에 신경 써야 해요. 첫 웨이브를 받아먹으며 신지드가 독을 뿌리며 지나가는 타이밍을 주의하세요.', lv3: '(W)\'초강력 접착제\'는 이동 스킬을 사용할 수 없게 하니 (Q)\'도약 공격\'을 쓸 때 바닥을 확인하세요. 신지드가 (E)\'던져넘기기\'로 근접하면 사거리가 짧으니 거리를 지켜 맞지 않도록 하고 평타는 (E)\'반격\'으로 피하세요. (W)\'무기 강화\'를 섞은 평타로 신지드를 압박하세요.', lv6: '신지드가 (R)\'광기의 물약\'을 사용하면 (Q)\'맹독의 자취\'로 고통스러운 상처를 남기니 정면 교환을 피하세요. (R)\'무기의 달인\'을 사용해 마법 저항력을 높인 뒤 (Q)\'도약 공격\'으로 신지드를 압박하세요. 신지드가 궁극기를 켜고 라인을 밀면 무리하게 쫓지 마세요.', item: '삼위일체를 첫 코어로 사용하여 전투력을 높이세요. 신발은 (Q)\'맹독의 자취\'의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 선택하세요.', spell: '점멸과 정화를 추천해요. (W)\'초강력 접착제\'의 둔화를 정화로 빠르게 해제하며 거리를 조절할 수 있어요.' },
    '아이번': { lv1: '1~2레벨 구간에서는 아이번의 (Q)\'덩굴뿌리\'에 속박되어 일방적으로 공격받지 않도록 주의하세요. 미니언 뒤에 숨어 (Q)\'덩굴뿌리\'를 피하며 (W)\'무기 강화\'를 켠 평타로 짧게 딜교환을 시도하세요.', lv3: '아이번이 (W)\'수풀 가꾸기\'를 설치하고 기본 공격으로 견제하면 (E)\'반격\'을 켜서 모든 공격을 회피하세요. 상대의 (Q)\'덩굴뿌리\'가 빠진 것을 확인한 뒤 (Q)\'도약 공격\'으로 진입해 기절을 넣고 강하게 압박하세요.', lv6: '(R)\'무기의 달인\'을 사용하여 방어력과 마법 저항력을 높인 뒤 과감하게 진입하세요. (R)\'데이지!\'가 일으키는 공중 띄우기 효과를 조심하며 아이번 본체를 빠르게 공격하세요.', item: '삼위일체와 헤르메스의 발걸음을 선택하세요. 헤르메스의 발걸음은 마법 저항력과 강인함을 제공하며 삼위일체는 공격력과 체력을 높여줘요.', spell: '점멸과 순간이동을 추천해요. 점멸로 진입 각을 만들고 순간이동으로 라인 복귀와 운영을 빠르게 하세요.' },
    '아지르': { lv1: '1~2레벨에는 (Q)\'사막의 맹습\'을 통한 견제를 조심하며 미니언 사이에서 거리를 유지하세요. 상대가 (W)\'일어나라!\'로 병사를 소환해 거리 조절을 할 때 (Q)\'도약 공격\'으로 진입할 타이밍을 노려요. 무리한 진입보다는 파밍에 집중하며 기회를 기다려요.', lv3: '아지르의 (W)\'일어나라!\' 병사 공격은 스킬 피해라 (E)\'반격\'으로 피할 수 없으니 병사가 서 있는 방향의 직선에서 벗어나세요. 상대가 (E)\'신기루\'로 병사에게 돌진해 거리를 벌리려 할 때 (Q)\'도약 공격\'을 적중시키는 것이 중요해요. (W)\'무기 강화\'를 섞어 짧고 강하게 공격하고 빠져나오세요.', lv6: '(R)\'무기의 달인\'을 켜서 마법 저항력을 높인 뒤 적극적으로 압박하세요. 상대가 (R)\'황제의 진영\'으로 밀어내려 할 때를 대비해 진입 타이밍을 신중히 결정해요. 아군 정글러가 근처에 있다면 (Q)\'도약 공격\'으로 빠르게 붙어 킬을 노려보세요.', item: '헤르메스의 발걸음과 삼위일체를 가세요. 마법 저항력을 챙기면서 공격력과 체력을 동시에 확보해요.', spell: '점멸과 점화를 추천해요. 점멸은 (Q)\'사막의 맹습\'이나 (R)\'황제의 진영\' 범위에서 빠져나오거나 거리를 좁힐 때 써요. 점화는 (E)\'신기루\'로 도망치려는 아지르를 마무리할 때 써요.' },
    '아칼리': { lv1: '아칼리는 (Q)\'오연투척검\'으로 둔화를 걸며 견제하니 거리 조절에 유의하세요. (P)\'암살자의 표식\' 원 경계 밖에서 평타를 맞지 않도록 주의하며 (Q)\'도약 공격\'은 아껴두세요. 초반에 무리한 교전보다는 아칼리의 기력이 빠진 타이밍을 기다리는 것이 좋아요.', lv3: '아칼리가 (E)\'표창곡예\'로 표식을 남기고 돌진할 때 (E)\'반격\'을 사용하여 대응하세요. (W)\'황혼의 장막\' 안에서는 아칼리를 대상으로 지정할 수 없으니 연막이 걷히거나 아칼리가 모습을 드러낼 때 (Q)\'도약 공격\'으로 진입하세요. 아칼리의 주요 스킬이 빠진 직후가 딜교환을 시도하기 좋은 시점이에요.', lv6: '아칼리가 (R)\'무결처형\'으로 진입하면 (R)\'무기의 달인\'을 사용하여 아칼리를 맞히고 방어력과 마법 저항력을 확보하세요. 연막 속의 아칼리는 지정할 수 없으므로 (Q)\'도약 공격\'을 신중히 사용하고 연막이 사라진 순간에 몰아붙이세요. 체력이 낮을 때는 아칼리의 두 번째 돌진을 조심하며 라인 관리와 정글 개입에 대비하세요.', item: '삼위일체를 첫 코어로 선택하여 공격력과 스킬 가속을 챙기세요. 신발은 아칼리의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 탈진을 추천해요. 탈진을 사용하면 아칼리의 돌진 피해량을 줄여서 생존하기 편해요.' },
    '아크샨': { lv1: '아크샨의 (Q)\'복수의 부메랑\' 견제가 시작되면 무리하게 미니언을 먹기보다 거리를 조절하며 버텨야 해요. 1~2레벨에는 (Q)\'도약 공격\'을 아껴두며 아크샨이 거리를 좁힐 때까지 기다리는 것이 좋아요. 아크샨의 공격을 받아내며 성장에 집중하세요.', lv3: '아크샨의 (E)\'영웅의 비상\'을 빼내는 데 집중하며 (Q)\'도약 공격\'으로 빠르게 붙는 것이 중요해요. (E)\'반격\'을 사용하여 아크샨의 기본 공격을 피하며 딜교환을 시도하세요. (W)\'무기 강화\'를 섞어 강력하게 압박하세요.', lv6: '(R)\'무기의 달인\'을 사용해 방어력과 마법 저항력을 높인 뒤 적극적으로 싸워 킬을 노려보세요. 아크샨의 (R)\'인과응보\'는 사거리가 길고 스킬 피해라 (E)\'반격\'으로 피할 수 없으니 조준 방향에서 벗어나세요. 아크샨이 (E)\'영웅의 비상\'으로 벽을 넘어 도망갈 수 있으므로 라인을 밀어넣어 압박하세요.', item: '판금 장화와 삼위일체를 추천해요. 아크샨의 평타 피해를 줄이기 위해 판금 장화를 가고 잭스의 지속 교전을 위해 삼위일체를 선택해요.', spell: '점멸과 점화예요. 아크샨을 빠르게 처치하여 킬각을 잡기 위해 점화를 선택해요.' },
    '아트록스': { lv1: '(Q)\'다르킨의 검\'의 끝부분에 맞으면 공중으로 띄워지니 범위를 피해 움직이세요. (P)\'사신 태세\'가 활성화된 평타는 체력을 회복하므로 무리하게 평타 교환을 하지 마세요. (W)\'무기 강화\'를 켜고 짧게 딜교환한 뒤 빠르게 빠지세요.', lv3: '(W)\'지옥사슬\'에 맞았다면 중심으로 끌려가기 전에 빠르게 범위를 벗어나세요. (E)\'반격\'은 기본 공격을 회피하고 광역 피해를 줄여주니, 아트록스가 평타를 섞어 공격할 때 사용하세요. 상대의 (Q)\'다르킨의 검\'이 모두 빠진 타이밍에 (Q)\'도약 공격\'으로 진입해 공격하세요.', lv6: '(R)\'세계의 종결자\'를 켠 아트록스는 체력 회복량이 크게 늘어나므로, 궁극기 지속 시간 동안은 정면 승부를 피하세요. (R)\'무기의 달인\'을 사용하여 방어력과 마법 저항력을 높인 뒤 (E)\'반격\'의 기절을 맞히면 마무리할 수 있어요. 정글러가 올 때 (Q)\'도약 공격\'으로 빠르게 합류하여 적을 압박하세요.', item: '삼위일체와 처형인의 대검을 먼저 갖춰 공격력을 높이고 (E)\'파멸의 돌진\'의 회복량을 줄이세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (P)\'사신 태세\'와 (E)\'파멸의 돌진\'으로 회복하는 아트록스에게 점화의 치유 감소 효과가 매우 효과적이에요.' },
    '암베사': { lv1: '암베사는 스킬 사용 후 (P)\'용사냥개의 발걸음\'으로 돌진하며 다음 평타를 강화하니 첫 교환을 주의하세요. (Q)\'교활한 휩쓸기\'의 범위를 살피며 미니언을 통해 거리를 조절하고 (Q)\'도약 공격\'으로 접근 타이밍을 잡으세요. 암베사가 스킬을 사용하여 기력을 소모한 직후에 대응하는 것이 좋아요.', lv3: '암베사가 (W)\'배척\'을 준비하는 동안 챔피언에게 피해를 받으면 내려찍는 피해가 늘어나니 준비 중에는 때리지 말고 거리를 두세요. (E)\'반격\'은 암베사의 평타를 흘리는 용도로 쓰세요. (E)\'찢어 가르기\'의 둔화에 걸리지 않도록 주의하며 (Q)\'교활한 휩쓸기\'가 빠진 뒤에 (Q)\'도약 공격\'으로 들어가 압박하세요.', lv6: '암베사의 (R)\'공개 처형\'은 먼저 제압한 뒤 내려쳐 기절시키는데, 제압 중에는 정화와 점멸 모두 쓸 수 없으니 걸리기 전에 위치를 조심해요. 궁극기를 쓰려는 낌새가 보이면 (R)\'무기의 달인\'으로 방어력을 높여 피해를 견뎌내세요. 암베사의 돌진 경로를 예측하며 라인을 관리하고 정글러와 함께 움직이세요.', item: '삼위일체를 첫 코어로 선택하여 공격력과 체력을 챙기세요. 신발은 암베사의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 암베사의 (R)\'공개 처형\' 이후 체력 회복을 억제하고 마무리 피해를 입히기에 좋아요.' },
    '애니비아': { lv1: '애니비아는 (Q)\'냉기 폭발\' 구체를 날려 기절시키려 하니 구체가 터지는 시점에 옆으로 피하세요. 초반에는 무리하게 진입하기보다 (Q)\'도약 공격\'으로 미니언을 챙기며 체력을 보존하세요. 구체가 멈춰서 터지기 전에 빠르게 거리를 좁히거나 뒤로 빠지는 거리 조절이 중요해요.', lv3: '(W)\'결정화\' 벽이 세워지면 경로가 막혀 접근이 어려우니 벽이 사라진 뒤에 움직이세요. (Q)\'냉기 폭발\'에 맞은 상태에서는 (E)\'동상\' 피해가 두 배로 들어오니 냉각 상태일 때는 교전을 피하세요. 상대의 스킬이 빠진 틈을 타 (E)\'반격\'을 켜고 진입해 기절시킨 뒤 (W)\'무기 강화\'로 강력한 피해를 입히세요.', lv6: '(R)\'얼음 폭풍\' 장판 위에서는 둔화 때문에 접근이 어려우니 장판 밖에서 기회를 엿보세요. (R)\'무기의 달인\'을 켜서 마법 저항력을 높이고 (Q)\'도약 공격\'으로 빠르게 파고들어 딜교환을 하세요. 애니비아가 쓰러져 (P)\'환생\' 알이 되면 즉시 공격해서 다시 살아나지 못하게 처리하세요.', item: '맬모셔스의 아귀를 첫 코어로 가서 마법 저항력을 높이고 생명선 보호막으로 생존력을 챙기세요. 신발은 (Q)\'냉기 폭발\'의 기절 지속 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 정화를 추천해요. (Q)\'냉기 폭발\'의 기절을 정화로 빠르게 풀어 다시 공격 기회를 잡으세요.' },
    '야스오': { lv1: '야스오는 (Q)\'강철 폭풍\'으로 일직선 견제를 하며 (P)\'낭인의 길\' 보호막으로 피해를 흡수해요. (Q)\'도약 공격\'으로 급격히 접근하기보다 평타로 보호막을 먼저 터뜨린 뒤에 짧게 교환하세요. (Q)\'강철 폭풍\' 중첩이 쌓여 회오리가 준비되었을 때는 거리를 벌려 띄워지는 것을 피하세요.', lv3: '야스오가 (E)\'질풍검\'으로 빠르게 파고들 때 (E)\'반격\'을 켜서 평타를 피하고 광역 피해를 줄인 뒤 기절을 노려요. (W)\'바람 장막\'은 투사체만 막기 때문에 (Q)\'도약 공격\'이나 (W)\'무기 강화\' 강화 평타는 그대로 적중하니 망설이지 말고 붙으세요. (E)\'반격\'의 기절을 맞힌 직후 (W)\'무기 강화\'를 섞어 빠르게 피해를 넣고 빠지세요.', lv6: '야스오의 (R)\'최후의 숨결\'은 공중에 뜬 적에게만 쓸 수 있으니 (Q)\'강철 폭풍\' 회오리에 맞아 뜨지 않도록 주의하세요. (R)\'무기의 달인\'을 사용해 방어력과 마법 저항력을 높이면 야스오의 치명타 피해를 견디며 강하게 압박할 수 있어요. 회오리에 맞으면 스킬을 쓸 수 없으니 (Q)\'강철 폭풍\' 중첩이 쌓였을 때는 거리를 두세요.', item: '삼위일체와 판금 장화를 추천해요. 삼위일체로 공격력과 공격 속도를 챙기고, 판금 장화로 야스오의 치명타 기본 공격 피해를 줄이세요.', spell: '점멸과 점화를 추천해요. (P)\'낭인의 길\' 보호막이 사라진 순간 점화의 고정 피해를 더해 빠르게 처치하세요.' },
    '오공': { lv1: '오공은 (Q)\'파쇄격\'으로 평타 사거리를 늘려 견제하고 (P)\'바위 피부\'로 시간이 갈수록 단단해져요. 1~2레벨에는 (W)\'무기 강화\'를 켜고 짧게 딜교환을 하거나 (Q)\'도약 공격\'으로 거리를 조절하며 체력을 관리하세요. 오공이 평타를 치러 다가올 때 짧게 때리고 빠지는 것이 좋아요.', lv3: '(E)\'근두운 급습\'으로 빠르게 붙는 오공의 평타 공격을 (E)\'반격\'으로 모두 피하며 스턴을 맞히세요. 오공이 (W)\'분신 전사\'로 투명해지면 성급하게 스킬을 쓰지 말고 진짜 오공이 나타날 때까지 기다리세요. (W)\'무기 강화\'를 사용한 평타로 딜교환을 마무리하며 이득을 보세요.', lv6: '오공의 (R)\'회전격\'에 맞으면 공중에 떠서 아무것도 할 수 없으니, 오공이 궁극기를 쓰면 즉시 옆으로 피하세요. (R)\'무기의 달인\'을 켜서 방어력과 마법 저항력을 높인 뒤 (Q)\'도약 공격\'으로 들어가 짧은 딜교환을 반복하세요. 정글러가 (R)\'회전격\'의 에어본에 맞춰 들어오는 갱킹을 조심하며 라인을 유지하세요.', item: '삼위일체를 첫 코어로 가서 공격 속도와 공격력을 높여 빠르게 공격하세요. 신발은 오공의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 오공의 (P)\'바위 피부\'로 인한 체력 재생을 억제하고 킬각을 잡기 위해 점화가 유용해요.' },
    '오로라': { lv1: '오로라는 (Q)\'이중 저주\'를 던지고 불러들이며 원거리에서 견제하고, (P)\'영혼 방호술\'로 체력을 회복해요. (Q)\'이중 저주\'가 돌아오는 경로에서 벗어나며 거리를 조절하세요. 상대가 무리하게 다가오면 (E)\'반격\'을 켜서 기본 공격을 피하며 기절시키세요.', lv3: '(E)\'마법의 문\'은 둔화를 걸고 뒤로 도약하니, 이 스킬이 빠진 뒤에 (Q)\'도약 공격\'으로 빠르게 접근하세요. (W)\'장막 너머로\'를 사용해 투명해진 오로라를 억지로 쫓지 말고, 다시 모습을 드러낼 때 (W)\'무기 강화\' 평타로 강하게 압박하세요.', lv6: '(R)\'세계의 경계\' 영역 안에서는 오로라가 자유롭게 이동하므로 무리하게 진입하지 말고 영역 밖으로 유도하세요. (R)\'무기의 달인\'을 켜서 방어력과 마법 저항력을 높인 뒤, 오로라의 도주기가 빠진 순간 (Q)\'도약 공격\'으로 붙어 빠르게 정리하세요.', item: '삼위일체와 헤르메스의 발걸음을 가세요. 삼위일체로 공격력과 체력을 챙기고, 헤르메스의 발걸음의 강인함으로 (E)\'마법의 문\'과 (R)\'세계의 경계\'의 둔화 시간을 줄여야 해요.', spell: '점멸과 점화를 추천해요. 오로라가 (P)\'영혼 방호술\'로 체력을 회복하는 것을 방해하고 마무리 피해를 주기 위해서예요.' },
    '오른': { lv1: '오른은 (P)\'간이 대장간\' 덕분에 초반부터 방어력과 마법 저항력이 높아서 짧은 딜교환으로는 체력을 많이 깎기 힘들어요. (Q)\'용암 균열\'의 균열 지점을 확인하고 옆으로 비켜서서 둔화를 피하세요. 무리하게 붙지 말고 평타를 섞으며 적절한 거리에서 딜교환을 시도하세요.', lv3: '벽 근처에 있으면 (E)\'화염 돌진\'에 맞고 띄워질 수 있으니 항상 중앙 쪽으로 자리를 잡으세요. (W)\'불꽃 풀무질\'의 마지막 불꽃을 맞으면 불안정 상태가 되어 군중 제어 지속시간이 길어지니 주의하세요. (E)\'반격\'을 켜서 오른의 기본 공격을 피하고 기절시킨 뒤 (W)\'무기 강화\'를 섞은 평타로 딜교환을 마무리하세요.', lv6: '(R)\'대장장이 신의 부름\'으로 소환된 정령에 맞으면 둔화되고 불안정 상태가 되며, 재시전 돌진에 맞으면 공중으로 띄워지니 정령의 경로를 잘 확인하세요. (R)\'무기의 달인\'을 사용해 방어력과 마법 저항력을 높이고 빠른 공격으로 체력을 깎으세요. 오른의 (E)\'화염 돌진\'이 빠진 타이밍에 (Q)\'도약 공격\'으로 들어가 킬각을 보세요.', item: '삼위일체를 첫 코어로 가서 공격력과 체력, 그리고 공격 속도를 챙겨 지속적으로 피해를 입히세요. 신발은 (Q)\'용암 균열\'이나 (R)\'대장장이 신의 부름\'의 둔화 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. 오른은 체력이 매우 높고 방어 성능이 좋아서 한 번에 처치하기 어려우니 순간이동으로 라인 관리를 하며 성장하세요.' },
    '올라프': { lv1: '올라프는 (Q)\'역류\'를 던져 방어력을 낮추고 이동 속도를 깎으며 강하게 압박해요. (Q)\'도약 공격\'으로 무작정 들어가기보다는 미니언을 챙기며 올라프의 (Q)\'역류\'를 피하는 것이 중요해요. 1~2레벨에는 올라프의 평타가 매우 강력하니 거리를 조절하며 대응하세요.', lv3: '올라프가 (W)\'버티기\'를 사용하여 보호막과 공격 속도를 얻었을 때는 무리하게 싸우지 마세요. (E)\'반격\'으로 올라프의 평타는 피할 수 있지만 (E)\'무모한 강타\'의 고정 피해는 막지 못하니 체력을 관리하며 타이밍을 보세요. 올라프가 도끼를 던지고 다시 주우러 가는 틈을 타 (Q)\'도약 공격\'으로 딜교환을 시도하세요.', lv6: '올라프가 (R)\'라그나로크\'를 사용하면 이동 방해 효과에 면역이 되므로 (E)\'반격\'의 기절 효과가 통하지 않아요. (R)\'라그나로크\' 지속 시간 동안에는 정면 대결을 피하고 (R)\'무기의 달인\'을 사용하여 방어력을 높이며 버티세요. 올라프의 궁극기가 끝난 뒤에 (Q)\'도약 공격\'과 (E)\'반격\'을 연계하여 킬각을 노리세요.', item: '첫 코어 아이템으로 삼위일체를 가고 신발은 올라프의 물리 피해를 줄여주는 판금 장화를 선택하세요. 삼위일체는 전투 지속력을 높여주고 판금 장화는 기본 공격 피해를 줄여줘요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 올라프의 (P)\'광전사의 분노\'에 의한 흡혈을 억제하세요.' },
    '요네': { lv1: '요네는 (Q)\'필멸의 검\'을 두 번 맞히면 돌풍으로 적을 띄워 올려요. 첫 번째 공격을 맞은 뒤에는 거리를 벌려 두 번째 중첩을 피하는 것이 좋아요. (Q)\'도약 공격\'을 아껴두며 (P)\'사냥꾼의 길\' 마법 피해를 조심하면서 미니언을 챙기세요.', lv3: '요네가 (E)\'영혼해방\'을 사용해 영혼 상태가 되면 육신이 있는 위치를 확인하며 (E)\'반격\'을 준비하세요. 요네의 (W)\'영혼 가르기\' 보호막을 먼저 빼기 위해 (Q)\'도약 공격\'을 아끼고, 보호막이 사라진 뒤에 (E)\'반격\'으로 요네의 기본 공격을 피하며 딜교환을 시도하세요.', lv6: '요네의 (R)\'운명봉인\'은 경로에 있는 적을 자신 쪽으로 끌어당기며 띄우니 팀 교전 시 일직선으로 서 있지 마세요. (R)\'무기의 달인\'을 사용해 방어력과 마법 저항력을 높여 요네의 강력한 연계를 버텨내세요. 요네가 (E)\'영혼해방\'에서 돌아오는 타이밍에 (Q)\'도약 공격\'과 (E)\'반격\'을 연계해 킬을 노리세요.', item: '삼위일체를 첫 코어로 가서 공격력과 공격 속도 그리고 체력을 모두 확보하세요. 신발은 요네의 물리 피해를 줄이기 위해 판금 장화를 선택하세요.', spell: '점멸과 점화를 추천해요. 요네의 (W)\'영혼 가르기\' 보호막이 사라진 뒤 점화로 마무리 피해를 더하세요.' },
    '요릭': { lv1: '요릭은 (Q)\'최후의 의식\'으로 추가 피해를 입히고 무덤을 생성하며 (P)\'영혼의 길잡이\' 망령으로 압박해요. 1~2레벨에는 무리하게 붙지 말고 (W)\'무기 강화\'를 섞은 짧은 평타 교환만 시도하세요. 망령이 소환되었을 때는 무리하게 딜교환하기보다 거리 조절을 하며 다음 기회를 기다리세요.', lv3: '요릭의 (E)\'애도의 안개\'를 맞으면 망령이 빠르게 몰려오니 (E)\'반격\'으로 망령과 요릭의 기본 공격을 모두 회피하고 기절시키세요. (W)\'망자의 진\' 벽에 갇혔을 때는 당황하지 말고 평타로 벽을 빠르게 파괴하세요. (W)\'무기 강화\'를 사용한 공격으로 요릭의 체력을 깎으며 짧은 딜교환을 반복하세요.', lv6: '(R)\'군도의 장송곡\'으로 소환된 안개 마녀와 망령들이 함께 공격하면 매우 아프니 (R)\'무기의 달인\'을 켜서 방어력과 마법 저항력을 높여 버티세요. 마녀가 있는 상태에서 정면 승부를 하기보다 요릭의 (E)\'애도의 안개\'가 빠진 타이밍에 (Q)\'도약 공격\'으로 진입해 빠르게 처리하세요. 라인을 밀어넣고 포탑 근처에서 대기하며 정글러의 개입을 유도하는 것이 편해요.', item: '삼위일체로 공격력과 체력을 보충해 지속 교전 능력을 높이세요. 신발은 요릭과 망령들의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 요릭이 소환물로 라인을 빠르게 밀 때 순간이동으로 복귀하며 손실을 줄여야 해요.' },
    '우디르': { lv1: '우디르가 (Q)\'야생 발톱\'으로 강력한 평타를 치며 다가오니 무리하게 붙지 마세요. (W)\'무기 강화\'를 켜고 짧게 딜교환을 한 뒤 빠르게 빠지는 방식으로 체력을 관리하세요.', lv3: '우디르가 (E)\'불길 쇄도\'로 돌진하며 기절시키려 할 때 (E)\'반격\'을 켜서 공격을 무효화하고 역으로 기절시키세요. (Q)\'야생 발톱\'의 추가 피해가 들어오는 타이밍에 (E)\'반격\'을 맞춰 사용하면 딜교환에서 앞서요. (Q)\'도약 공격\'은 우디르의 스킬이 빠진 뒤에 진입 수단으로 활용하세요.', lv6: '(R)\'무기의 달인\'을 사용하여 방어력과 마법 저항력을 높이고 정면 승부를 보세요. 우디르가 (R)\'날개 돋친 폭풍\'으로 둔화를 걸면 무리하게 쫓지 말고 (E)\'반격\'으로 스턴을 맞히는 데 집중하세요. 우디르가 (E)\'불길 쇄도\'를 재사용해 이동 불가 면역 상태가 되면 기절이 통하지 않으니 잠시 거리를 두세요.', item: '몰락한 왕의 검과 판금 장화를 추천해요. 몰락한 왕의 검은 공격 속도와 생명력 흡수를 제공하며, 판금 장화는 우디르의 기본 공격 피해를 줄여줘요.', spell: '점멸과 점화를 추천해요. 우디르가 (W)\'강철 갑옷\'으로 체력을 회복하는 것을 점화로 억제하며 킬각을 잡으세요.' },
    '우르곳': { lv1: '우르곳은 (Q)\'부식성 폭약\'으로 둔화를 걸고 (P)\'화염의 메아리\'로 평타 피해를 입히며 초반을 보내요. (Q)\'부식성 폭약\'이 떨어지는 곳을 피해 거리를 유지하고, 우르곳이 스킬을 쓴 뒤에 (Q)\'도약 공격\'으로 들어가서 짧게 싸우세요.', lv3: '우르곳의 (W)\'심판의 원\'은 다른 스킬을 맞힌 적을 우선 공격하니 (Q)\'부식성 폭약\'을 먼저 피하는 것이 중요해요. 우르곳이 (E)\'경멸\'로 돌진해 나를 뒤로 던지기 전에 (Q)\'도약 공격\'으로 위치를 잡고, 평타는 (E)\'반격\'으로 피하며 딜교환하세요.', lv6: '우르곳의 (R)\'불사의 공포\'는 체력이 낮을 때 제압을 걸어 처형할 수 있으니 섬광탄을 맞았다면 즉시 거리를 벌리세요. (R)\'무기의 달인\'을 사용해 방어력을 높여 우르곳의 공격을 견디고, (Q)\'도약 공격\'을 활용해 우르곳의 (E)\'경멸\' 돌진을 피하며 싸우세요.', item: '삼위일체를 첫 코어로 가서 전투를 이어가세요. 신발은 우르곳의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 우르곳의 (R)\'불사의 공포\' 처형 범위에 들어가기 전에 점화로 빠르게 적을 처치하세요.' },
    '워윅': { lv1: '워윅은 (Q)\'야수의 송곳니\'를 사용해 도약하며 피해를 입히고 체력을 회복하니 첫 교환에서 체력을 너무 많이 내주지 마세요. 1~2레벨에는 (E)\'반격\'을 사용하여 워윅의 기본 공격을 피하며 딜교환을 시도하는 것이 좋아요.', lv3: '워윅이 (E)\'원시의 포효\'를 사용하면 받는 피해가 줄어드니 그 지속 시간 동안에는 (Q)\'도약 공격\'으로 무리하게 진입하지 마세요. 워윅의 기본 공격을 (E)\'반격\'으로 피하며 기절을 맞히면 딜교환에서 앞서갈 수 있어요.', lv6: '워윅이 (R)\'무한의 구속\'으로 제압하면 정화와 점멸, 스킬을 모두 쓸 수 없으니 도약 경로에서 미리 벗어나세요. 워윅의 체력이 낮아지면 (P)\'끝없는 허기\'로 회복량이 늘어나니 (E)\'반격\'을 활용해 빠르게 전투를 끝내세요. 제압은 정화로 풀 수 없다는 점도 기억하세요.', item: '삼위일체를 첫 코어로 올려서 능력치를 챙기세요. 신발은 워윅의 마법 피해와 공포 지속 시간을 줄여주는 헤르메스의 발걸음을 선택하세요.', spell: '점멸과 점화를 추천해요. 점화로 워윅의 (Q)\'야수의 송곳니\'와 (P)\'끝없는 허기\'에 의한 체력 회복을 줄이세요.' },
    '이렐리아': { lv1: '이렐리아는 (Q)\'칼날 쇄도\'로 미니언을 타고 빠르게 접근하며 체력을 회복해요. 1~2레벨에는 무리하게 교전하지 말고 (W)\'무기 강화\'를 활용해 짧게 공격한 뒤 거리를 벌리세요. 미니언 체력이 낮은 쪽으로 서 있으면 이렐리아의 진입이 쉬우니 위치를 주의하세요.', lv3: '(E)\'쌍검협무\'의 두 번째 칼날이 날아오는 경로를 피해 기절과 표식을 피하세요. 이렐리아가 (Q)\'칼날 쇄도\'로 진입할 때 (E)\'반격\'을 켜면 기본 공격을 모두 피하고 기절까지 시킬 수 있어요. (W)\'무기 강화\'는 이렐리아가 (W)\'저항의 춤\'으로 피해를 줄이기 전에 빠르게 사용하세요.', lv6: '(R)\'선봉진격검\'의 결계 안에서 둔화되면 (Q)\'도약 공격\'으로 빠르게 빠져나오거나 거리를 잡으세요. (R)\'무기의 달인\'을 사용해 방어력과 마법 저항력을 높이면 이렐리아의 폭발적인 피해를 버티기 편해요. (E)\'쌍검협무\'가 빠진 타이밍에 진입해 교전을 유도하고 정글의 도움을 받으세요.', item: '몰락한 왕의 검을 첫 코어로 가서 공격 속도와 생명력 흡수로 지속 교전 능력을 높이세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 효율적이에요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 (Q)\'칼날 쇄도\'를 통한 이렐리아의 체력 회복을 방해할 수 있어요.' },
    '일라오이': { lv1: '일라오이는 (P)\'고대신의 예언자\'로 벽 근처에 촉수를 소환해 공격하니, 가급적 라인 중앙에서 싸우세요. (Q)\'촉수 강타\'의 범위를 피하며 짧게 딜교환하고, (W)\'무기 강화\'를 섞어 평타로 견제해 보세요. 벽 근처로 끌려가면 촉수 피해가 커지니 주의하세요.', lv3: '(E)\'영혼의 시험\'에 맞으면 내 영혼이 분리되고 일라오이가 영혼을 때리면 피해 일부가 나에게 들어오니, 영혼에서 멀어져 숙주가 되지 않도록 영혼 근처에서 교환하세요. (W)\'혹독한 가르침\'과 기본 공격은 (E)\'반격\'으로 회피하고 기절시킨 뒤 (Q)\'도약 공격\'으로 추격하세요. 촉수가 많은 지형에서는 오래 머물지 말고 빠르게 치고 빠지는 것이 좋아요.', lv6: '(R)\'믿음의 도약\'을 사용해 촉수를 대량으로 소환하면 즉시 거리를 벌려 피해를 최소화하세요. 일라오이의 궁극기 지속 시간이 끝나면 (R)\'무기의 달인\'을 켜고 방어력과 마법 저항력을 높여 강하게 압박하세요. 정글러가 올 때 촉수 범위 밖에서 (Q)\'도약 공격\'으로 진입해 빠르게 처리하는 것이 좋아요.', item: '삼위일체와 판금 장화를 추천해요. 삼위일체로 공격력과 체력을 보충하고, 판금 장화로 일라오이의 기본 공격 피해를 줄이세요.', spell: '점멸과 순간이동을 추천해요. 일라오이가 라인을 밀어붙이는 경향이 있으니 순간이동으로 빠르게 복귀해 손해를 줄이세요.' },
    '자크': { lv1: '자크는 (Q)\'탄성 주먹\'으로 거리를 벌리며 둔화를 걸고 조각을 모으려 할 거예요. 1~2레벨에는 무리하게 싸우기보다 미니언을 챙기며 조각이 생기는 위치를 확인하세요. 자크가 조각을 주우러 올 때 (Q)\'도약 공격\'으로 빠르게 붙어 압박하는 것이 좋아요.', lv3: '자크가 (E)\'새총 발사\'를 충전하는 동안 착지 지점을 읽고 벗어나며, 광역 피해를 줄이려면 (E)\'반격\'을 미리 켜두세요. 공중에 뜨면 스킬을 쓸 수 없으니 맞기 전에 쓰세요. 자크가 (Q)\'탄성 주먹\'을 사용한 뒤에는 (Q)\'도약 공격\'과 (W)\'무기 강화\'를 활용해 짧고 강하게 딜교환하고 빠지세요.', lv6: '자크가 (R)\'바운스!\'로 공중에 띄우려 할 때 (R)\'무기의 달인\'을 사용하여 방어력을 높여 대응하세요. 자크가 (P)\'세포 분열\'로 인해 조각으로 갈라졌을 때 (Q)\'도약 공격\'으로 빠르게 접근해 조각을 모두 제거해야 해요. 자크가 체력이 낮아 조각으로 분리되기 전에 (W)\'무기 강화\'와 평타를 섞어 최대한 빠르게 처치하는 것이 중요해요.', item: '삼위일체를 첫 코어로 선택하여 전투 지속력을 높이세요. 신발은 자크의 마법 피해를 줄여주는 헤르메스의 발걸음을 신으세요.', spell: '점멸과 점화를 추천해요. 점화로 자크의 (P)\'세포 분열\'을 통한 체력 회복을 억제하며 킬을 노리세요.' },
    '자헨': { lv1: '자헨은 (Q)\'다르킨의 글레이브\'로 연속 공격하며 체력을 회복하니 평타 교환을 오래 하지 마세요. (P)\'전쟁 단련\' 중첩이 쌓이면 자헨의 공격력이 올라가니 짧게 딜교환하고 물러나세요. (W)\'무기 강화\'를 섞은 기본 공격으로 짧게 견제해요.', lv3: '(E)\'반격\'을 켜서 자헨의 (Q)\'다르킨의 글레이브\' 강화 평타를 피하고 (E)\'찬란한 쇄도\'의 광역 피해를 줄이세요. (W)\'공포의 귀환\'에 끌려가면 위험하니 자헨의 정면에서 벗어난 뒤 (Q)\'도약 공격\'으로 진입해요. 자헨이 스킬을 다시 사용해 띄우려 할 때 (E)\'반격\'의 기절로 흐름을 끊으세요.', lv6: '자헨이 (R)\'단호한 판결\'로 날아오르면 낙하 지점을 빠르게 피해서 체력 회복을 막으세요. (R)\'무기의 달인\'을 사용해 방어력과 마법 저항력을 높여 자헨의 폭발적인 피해를 버티세요. (P)\'전쟁 단련\'으로 부활할 수 있으니 체력을 다 깎아도 바로 방심하지 마세요.', item: '삼위일체를 첫 코어로 가서 공격 속도와 체력을 보충하고 강력한 피해를 입히세요. 신발은 자헨의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 자헨은 (Q)\'다르킨의 글레이브\'와 (R)\'단호한 판결\'로 체력을 회복하니 점화의 치유 감소 효과가 필요해요.' },
    '제이스': { lv1: '제이스는 캐논 형태에서 (Q)\'전격 폭발\'로 견제하며 거리를 벌리려 해요. (Q)\'전격 폭발\'의 투사체 방향을 잘 살피며 미니언과 함께 체력을 관리하세요. 제이스가 (Q)\'하늘로!\'를 쓰며 들어올 때는 (Q)\'도약 공격\'으로 즉시 거리를 좁힐 준비를 하세요.', lv3: '제이스의 (E)\'천둥 강타\'는 단일 대상을 밀쳐내는 스킬이라 (E)\'반격\'으로 피해를 줄일 수 없으니 이 스킬이 빠진 뒤에 접근하세요. (W)\'초전하\'를 사용한 제이스의 빠른 공격 속도를 조심하며 (W)\'무기 강화\'를 섞은 딜교환을 시도하세요. 제이스가 형태를 바꾸는 순간을 노려 (Q)\'도약 공격\'으로 붙는 것이 중요해요.', lv6: '(R)\'머큐리 캐논\'으로 방어력을 깎으려는 제이스의 원거리 공격을 조심하며 라인을 관리하세요. 제이스의 (E)\'천둥 강타\'가 빠진 뒤에 (R)\'무기의 달인\'과 (Q)\'도약 공격\'을 사용해 빠르게 파고드세요. (E)\'반격\'으로 제이스의 기본 공격을 피하며 싸우면 충분히 킬을 노릴 수 있어요.', item: '삼위일체를 첫 코어로 가서 공격력과 체력 그리고 스킬 가속을 챙기세요. 신발은 제이스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 제이스가 형태를 바꾸는 틈을 이용해 점화를 사용하면 킬각을 잡기 쉬워요.' },
    '초가스': { lv1: '초가스는 (Q)\'파열\'로 적을 공중에 띄워 둔화를 주니 바닥 표시를 보고 빠르게 피하세요. (E)\'날카로운 가시\'가 평타마다 정면의 적을 둔화시키니 정면에서 오래 싸우지 마세요. (P)\'육식\'으로 체력을 회복하는 초가스를 평타로 견제하며 체력을 깎으세요.', lv3: '(W)\'흉포한 울부짖음\'에 침묵되면 (Q)\'도약 공격\'을 쓸 수 없으니 침묵이 끝난 뒤에 진입하세요. (E)\'반격\'을 켜면 (E)\'날카로운 가시\'의 기본 공격 피해를 회피하며 초가스를 기절시킬 수 있어요. 기절시킨 틈에 (W)\'무기 강화\'를 섞어 짧고 강하게 딜교환을 하세요.', lv6: '(R)\'포식\'은 방어력을 무시하는 큰 고정 피해를 입히니 체력이 낮을 때 무리하게 붙지 마세요. 교전 시작 시 (R)\'무기의 달인\'을 사용해 방어력과 마법 저항력을 높여 적의 공격을 버텨내세요. (Q)\'파열\'에 공중에 뜨면 스킬을 쓸 수 없으니 주의하며 (Q)\'도약 공격\'으로 거리를 조절하세요.', item: '삼위일체를 첫 코어로 가서 공격력과 체력을 확보해 지속 싸움 능력을 높이세요. 신발은 마법 저항력을 주고 침묵과 둔화 지속시간을 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 초가스의 (P)\'육식\' 회복 효과를 줄여 킬각을 잡으세요.' },
    '카밀': { lv1: '카밀은 (P)\'적응형 방어 체계\'로 평타 시 보호막을 얻고 (Q)\'정확성 프로토콜\'로 강력한 한 방을 넣어요. 보호막이 있을 때는 짧게 딜교환하고, (Q)\'정확성 프로토콜\'의 강화 공격 타이밍에는 거리를 벌리세요. 1~2레벨에는 무리하게 붙기보다 기본 공격으로 천천히 압박하세요.', lv3: '카밀의 (W)\'전술적 휩쓸기\' 바깥쪽에 맞으면 둔화되고 체력을 회복시켜주니, (Q)\'도약 공격\'으로 빠르게 안쪽으로 파고드세요. 카밀이 (E)\'갈고리 발사\'로 진입해 기절시키려 할 때 (E)\'반격\'을 켜서 기본 공격을 피하고 역으로 기절시키세요. (W)\'무기 강화\'를 섞은 평타로 카밀의 보호막을 빠르게 걷어내세요.', lv6: '(R)\'마법공학 최후통첩\'에 갇히면 탈출할 수 없으니, 그 안에서 (E)\'반격\'을 사용해 카밀의 공격을 피하고 기절을 노리세요. (R)\'무기의 달인\'을 켜서 방어력과 마법 저항력을 높이고 빠르게 연속 공격을 적중시키세요. 벽 근처에서는 (E)\'갈고리 발사\'에 쉽게 노출되니 라인 중앙에서 관리하세요.', item: '삼위일체를 가서 공격력과 공격 속도, 체력을 모두 챙기세요. 신발은 카밀의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 카밀의 (W)\'전술적 휩쓸기\' 회복량을 줄일 수 있어요.' },
    '카사딘': { lv1: '카사딘이 (Q)\'무의 구체\'를 사용하여 보호막을 형성하기 전에 (Q)\'도약 공격\'으로 빠르게 진입하세요. 초반에는 미니언을 안전하게 챙기며 적절한 거리를 유지하는 것이 중요해요.', lv3: '(E)\'반격\'을 사용해 카사딘의 기본 공격을 받아내며 딜교환을 하세요. (E)\'힘의 파동\'의 둔화는 막을 수 없으니 원뿔 범위에서 벗어나세요. 카사딘이 (Q)\'무의 구체\'로 보호막을 얻기 전에 (W)\'무기 강화\'를 섞어 공격하는 것이 좋아요.', lv6: '카사딘이 (R)\'균열 이동\'으로 거리를 벌리려 할 때 (Q)\'도약 공격\'으로 추격하며 킬각을 보세요. (R)\'무기의 달인\'을 켜서 마법 저항력을 높인 뒤 싸우고 정글러의 개입을 유도하세요.', item: '헤르메스의 발걸음과 삼위일체를 가요. 카사딘의 마법 피해에 대응하기 위해 헤르메스의 발걸음을 선택하고 공격적인 성장을 위해 삼위일체를 올려요.', spell: '점멸과 점화를 추천해요. 점멸로 (R)\'균열 이동\'으로 빠지는 카사딘을 따라붙거나 (E)\'힘의 파동\' 범위에서 벗어날 수 있어요. 점화는 체력이 낮아진 카사딘을 마무리할 때 써요.' },
    '카시오페아': { lv1: '1~2레벨에는 (Q)\'맹독 폭발\'과 (E)\'쌍독니\' 견제를 최대한 버티며 경험치를 챙기세요. 무리하게 진입하기보다 미니언을 통해 체력 관리를 하며 기회를 엿봐야 해요. (E)\'반격\'을 켜고 접근해 기절을 노리되 상대의 거리 조절에 주의하세요.', lv3: '(W)\'독기의 늪\'이 깔려 있으면 (Q)\'도약 공격\'을 사용할 수 없으니 주의하세요. 상대의 (W)\'독기의 늪\'이 빠진 타이밍에 (Q)\'도약 공격\'으로 진입한 뒤 (W)\'무기 강화\'로 강력한 피해를 주세요. (E)\'반격\'은 접근 과정에서 상대의 기본 공격 견제를 막는 용도로 활용하세요.', lv6: '(R)\'석화의 응시\'는 정면에서 바라보면 기절하고 등지면 둔화되니 카시오페아와 마주 선 상태로 사거리 안에 오래 머물지 마세요. (R)\'무기의 달인\'을 켜서 방어력과 마법 저항력을 높인 뒤 빠르게 붙어 공격하세요. (Q)\'도약 공격\' 진입 전 상대의 주요 스킬 쿨타임을 확인하고 정글의 도움을 받는 것이 좋아요.', item: '헤르메스의 발걸음과 몰락한 왕의 검을 추천해요. 마법 저항력과 강인함으로 제어 효과를 줄이고 공격 속도와 생명력 흡수로 전투를 지속하며 빠르게 공격하세요.', spell: '점멸과 점화를 추천해요. (E)\'쌍독니\'의 체력 회복을 억제하고 부족한 킬 결정력을 보완하기 위해 점화가 필요해요.' },
    '케넨': { lv1: '케넨은 (Q)\'천둥의 표창\'으로 멀리서 견제하며 (P)\'폭풍의 표식\'을 쌓으려 해요. 표창이 날아오는 궤적에서 벗어나며 거리 조절을 하고, 기회가 왔을 때 (W)\'무기 강화\'를 켜고 짧게 딜교환을 하세요. 표식이 세 번 쌓여 기절하기 전에 빠르게 빠져나와야 해요.', lv3: '(E)\'번개 질주\'로 들어오는 케넨의 움직임을 읽고 (E)\'반격\'을 사용하여 기본 공격을 회피하고 기절을 시키세요. 케넨이 (W)\'전류 방출\'로 표식을 더 쌓으려 하면 (Q)\'도약 공격\'으로 거리를 좁혀 강력하게 압박하세요. (E)\'반격\'의 기절이 성공했다면 (W)\'무기 강화\'와 평타를 섞어 빠르게 피해를 입히세요.', lv6: '케넨이 (R)\'날카로운 소용돌이\'를 켜고 진입하면 (E)\'반격\'으로 피해를 줄이며 기절을 노리세요. (R)\'무기의 달인\'을 사용하여 마법 저항력을 높인 뒤 (Q)\'도약 공격\'으로 붙어 빠르게 딜교환을 끝내세요. 정글 개입 시 (R)\'날카로운 소용돌이\'의 기절이 순식간에 쌓일 수 있으니 주의하며 거리를 두세요.', item: '삼위일체와 헤르메스의 발걸음을 추천해요. 삼위일체로 공격력과 체력을 챙기고, 헤르메스의 발걸음의 마법 저항력과 강인함으로 기절 지속시간을 줄이세요.', spell: '점멸과 순간이동을 추천해요. 케넨의 견제를 버티며 라인 관리를 하고 점멸로 (E)\'반격\'의 기절 각을 만드세요.' },
    '케일': { lv1: '케일은 (P)\'거룩한 승천\'으로 레벨이 오를수록 강해지니 초반에 강하게 압박해야 해요. (Q)\'광휘의 일격\'에 맞으면 이동 속도와 방어력 등이 감소하니 조심하세요. (Q)\'도약 공격\'을 활용해 적극적으로 거리를 좁히며 압박하세요.', lv3: '케일이 (Q)\'광휘의 일격\'을 사용한 직후 (E)\'반격\'을 켜고 들어가 케일의 평타를 피하세요. (E)\'반격\'은 스킬 피해를 피하지 못하니 (Q)\'광휘의 일격\'이 빠졌는지 먼저 확인해요. 케일이 (W)\'천상의 축복\'으로 도망가려 하면 (Q)\'도약 공격\'으로 따라붙고 (E)\'화염주문검\' 추가 피해가 들어오기 전에 교전을 끝내세요.', lv6: '케일이 (R)\'신성한 심판\'을 사용해 무적 상태가 되면 억지로 싸우지 말고 빠져 있어야 해요. 무적 효과가 끝난 직후에 (R)\'무기의 달인\'을 켜고 (Q)\'도약 공격\'으로 진입하여 킬각을 보세요. 케일의 성장을 늦추기 위해 정글러를 호출해 압박하는 것도 좋은 방법이에요.', item: '삼위일체를 첫 코어로 선택해 공격력과 공격 속도를 모두 챙기세요. 신발은 케일의 마법 피해를 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 초반에 점화로 케일의 체력을 깎고 킬을 만들어 성장을 늦춰야 해요.' },
    '코그모': { lv1: '1~2레벨 구간에는 (Q)\'부식성 침\'으로 인해 체력이 빠질 수 있으니 주의해요. (Q)\'도약 공격\'을 아끼며 미니언을 챙기고 거리를 조절하세요. (E)\'공허의 분비물\'이 남긴 흔적을 밟지 않도록 조심하며 움직여요.', lv3: '(E)\'반격\'을 사용해 코그모의 기본 공격을 피하며 접근하세요. 코그모의 (W)\'생체마법 폭격\'이 켜진 상태에서는 사거리가 길어지니 (Q)\'도약 공격\'으로 빠르게 파고들어야 해요. (W)\'무기 강화\'를 섞어 짧고 강하게 교환해요.', lv6: '(R)\'무기의 달인\'을 켜고 방어력을 높인 뒤 코그모에게 돌진하세요. 코그모의 (R)\'살아있는 곡사포\' 사거리가 매우 길기 때문에 (Q)\'도약 공격\'을 신중하게 사용해야 해요. 정글러를 불러 코그모를 압박하는 것이 좋아요.', item: '마법 피해를 줄이기 위해 헤르메스의 발걸음을 신어요. 공격력과 스킬 가속을 위해 삼위일체를 첫 코어로 선택해요.', spell: '점멸과 점화를 사용해요. 코그모의 체력을 빠르게 깎아 킬을 내기 위해서예요.' },
    '코르키': { lv1: '(Q)\'인광탄\'의 사거리에 주의하며 미니언 사이에서 거리를 조절하세요. 1~2레벨에는 무리하게 들어가기보다 상대의 견제를 받아내며 기회를 보세요. (Q)\'도약 공격\'을 사용하여 상대에게 접근할 타이밍을 신중하게 결정하세요.', lv3: '(E)\'반격\'을 사용하여 상대의 공격을 받아내며 (Q)\'도약 공격\'으로 거리를 좁히세요. 상대의 (E)\'개틀링 건\'을 먼저 빼도록 유도한 뒤 진입하는 것이 효율적이에요. (W)\'무기 강화\'를 섞어 짧고 강하게 딜교환을 한 뒤 거리를 벌리세요.', lv6: '(R)\'무기의 달인\'을 사용하여 방어력을 높인 뒤 적극적으로 싸워보세요. 상대의 (R)\'미사일 폭격\'이 장전된 상태라면 진입할 때 조심해야 해요. 라인을 밀어넣고 정글러의 개입에 대비하며 시야를 확보하세요.', item: '헤르메스의 발걸음과 삼위일체를 선택하세요. 상대의 마법 피해를 견디면서 전투력을 높일 수 있어요.', spell: '점멸과 점화. 점화로 상대의 체력을 깎고 마무리 피해를 입히기 좋아요.' },
    '퀸': { lv1: '퀸은 (P)\'매사냥\' 표식을 활용한 평타와 (Q)\'실명 공격\'으로 원거리에서 압박을 가해요. (Q)\'실명 공격\'은 미니언 뒤에 숨어서 피하며 체력을 보존하는 것이 중요해요. 퀸이 (E)\'공중제비\'로 거리를 좁히며 들어올 때 (E)\'반격\'을 사용하여 공격을 회피하며 대응하세요.', lv3: '(Q)\'도약 공격\'으로 접근할 때 퀸이 (E)\'공중제비\'로 거리를 벌리려 할 수 있으니 주의하세요. 퀸의 기본 공격을 (E)\'반격\'으로 흘려보내며 딜교환을 시도하고 (W)\'무기 강화\'를 섞어주세요. 퀸이 (W)\'예리한 감각\'의 이동 속도 증가를 활용해 도망가지 못하게 붙어야 해요.', lv6: '퀸이 (R)\'후방 지원\'으로 빠르게 움직이며 로밍을 시도할 수 있으니 라인 관리에 신경 쓰세요. 전투 중에는 (R)\'무기의 달인\'을 켜서 방어력을 높이고 퀸이 (R)\'후방 지원\' 후 착지할 때 (Q)\'도약 공격\'으로 진입하세요. 퀸이 (E)\'공중제비\'로 도망가려 해도 (E)\'반격\'과 함께 몰아붙이면 처치할 수 있어요.', item: '퀸의 물리 피해를 줄이기 위해 판금 장화가 적합해요. 첫 코어 아이템은 공격력과 체력을 모두 제공하는 삼위일체를 선택하세요.', spell: '점멸과 점화를 추천해요. 퀸이 (E)\'공중제비\'로 물러난 뒤 빈틈을 노려 점화로 확실하게 처치하세요.' },
    '크산테': { lv1: '크산테는 (Q)\'엔토포 타격\'으로 둔화를 걸고 두 번 맞히면 끌어당겨요. (Q)\'엔토포 타격\'의 첫 타를 맞았다면 거리 조절을 해서 충격파에 끌려가지 않도록 주의하세요. 1~2레벨에는 (W)\'무기 강화\'를 섞은 평타로 짧게 딜교환하고 빠르게 빠지는 것이 좋아요.', lv3: '크산테의 (W)\'길을 여는 자\'는 저지 불가 돌진이라 (E)\'반격\'으로도 막을 수 없으니, 충전 모션이 보이면 옆으로 피하세요. (E)\'반격\'은 크산테의 기본 공격을 막아내며 기절을 시키기에 좋으니, 상대가 (E)\'발놀림\'으로 진입할 때 켜서 딜교환을 시작하세요. (Q)\'도약 공격\'은 (E)\'발놀림\'의 보호막이 빠진 뒤에 사용해 확실하게 딜을 넣으세요.', lv6: '(R)\'총공세\'를 사용한 크산테는 방어력이 낮아지지만 피해량과 흡혈이 크게 늘어나니, 정면에서 계속 싸우기보다 (R)\'무기의 달인\'으로 방어력을 높여 버티며 딜을 넣으세요. (R)\'총공세\' 상태의 (W)\'길을 여는 자\'는 더 이상 기절시키거나 밀어내지 않으니 적극적으로 (E)\'반격\'을 활용해 딜교환을 이끄세요. 벽 근처에서는 (R)\'총공세\'로 인해 벽 너머로 밀려나 정글러에게 노출될 수 있으니 위치 선정에 주의하세요.', item: '삼위일체를 첫 코어로 가서 공격력, 체력, 공격 속도를 모두 챙기세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 크산테는 체력이 많아 처치하기 어려우니 순간이동으로 라인 복귀를 빠르게 하세요.' },
    '클레드': { lv1: '클레드는 (Q)\'덫날리기\'로 적을 붙잡아 끌어당기며 초반에 강하게 압박해요. 덫에 맞은 뒤 클레드와 가까이 머물면 끌려가며 추가 피해를 입으니 즉시 거리를 벌리세요. 클레드가 (Q)\'덫날리기\'를 빗맞혔을 때 (Q)\'도약 공격\'으로 진입해 짧은 딜교환을 하세요.', lv3: '클레드가 (W)\'버럭버럭\'을 사용하여 공격 속도가 빨라진 구간에는 평타 교환을 피하세요. 클레드가 (E)\'이랴!\'로 돌진해올 때 (E)\'반격\'을 사용하여 기본 공격을 회피하고 기절시키세요. 클레드가 스칼에서 내리면 챔피언에 대한 피해량이 줄어드니 (W)\'무기 강화\'를 사용하여 공격하세요.', lv6: '클레드가 (R)\'돌겨어어억!!!\'을 사용해 보호막을 두르고 돌진하면 일직선상에 서 있지 마세요. 클레드가 스칼에서 내려 용기를 채우려 할 때 (Q)\'도약 공격\'으로 빠르게 붙어 압박하세요. 라인을 당겨서 받아내며 정글러의 개입을 유도하는 것이 좋아요.', item: '삼위일체와 판금 장화를 추천해요. 삼위일체로 공격력과 체력을 얻고 판금 장화의 기본 공격 피해 감소 효과로 클레드의 공격을 버티세요.', spell: '점멸과 점화를 추천해요. 클레드가 스칼에서 내린 뒤 빠르게 처치하기 위해서 점화가 필요해요.' },
    '탐켄치': { lv1: '탐 켄치는 (Q)\'혀 채찍\'으로 견제하며 (P)\'절대 미각\' 중첩을 쌓으려 해요. (Q)\'혀 채찍\'은 처음 맞는 유닛에 적중하니 미니언 뒤에 서서 피해를 막으세요. (W)\'무기 강화\'를 켜고 짧게 평타를 교환하되 중첩이 세 번 쌓이기 전에 뒤로 물러나세요.', lv3: '탐 켄치의 (W)\'심연 잠수\'는 상대를 공중에 띄우니, 잠수 표시가 보이면 즉시 범위 밖으로 피하세요. (E)\'반격\'으로는 기본 공격만 피할 수 있고 (W)\'심연 잠수\'의 띄우기는 막지 못하니 주의하세요. 상대의 (W)\'심연 잠수\'가 빠진 후에 (Q)\'도약 공격\'으로 진입해 공격하세요.', lv6: '(P)\'절대 미각\' 중첩이 세 번 쌓인 상태에서 붙으면 (R)\'집어삼키기\'에 먹혀 큰 피해를 입어요. 중첩이 쌓이기 전 (R)\'무기의 달인\'을 켜고 강력한 딜교환을 시도하세요. (E)\'두꺼운 피부\' 보호막이 활성화된 동안에는 공격 효율이 낮으니 보호막이 사라진 뒤에 집중적으로 공격하세요.', item: '몰락한 왕의 검을 첫 코어로 가서 체력이 높은 탐 켄치에게 효율적으로 피해를 입히세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 탐 켄치의 (Q)\'혀 채찍\'과 (E)\'두꺼운 피부\'를 통한 체력 회복을 방해하세요.' },
    '트런들': { lv1: '트런들은 (Q)\'깨물기\'로 공격력을 훔치며 초반 평타 교환이 매우 강해요. (W)\'무기 강화\'로 빠르게 한 번씩 치고 빠지며 거리를 조절하세요. 트런들이 (W)\'얼음 왕국\'을 깔면 공격 속도가 오르니 영역 밖에서 대치하세요.', lv3: '(E)\'반격\'을 켜서 트런들의 기본 공격을 모두 피하고 기절시키는 것이 핵심이에요. (E)\'얼음 기둥\'에 밀려나거나 길이 막히면 (Q)\'도약 공격\'을 쓰기 어려우니 기둥이 빠진 뒤에 진입하세요. (W)\'무기 강화\'를 섞어 짧게 딜교환하고 스턴으로 마무리하세요.', lv6: '(R)\'무기의 달인\'을 사용해 방어력을 올렸을 때 (R)\'진압\'을 맞으면 능력치를 많이 뺏기니 주의하세요. 트런들의 (R)\'진압\' 지속 시간이 끝난 뒤에 (Q)\'도약 공격\'으로 들어가 공격하세요. (E)\'얼음 기둥\'으로 도주로를 막는 특성을 이용해 정글러를 부르기 좋은 구도를 만드세요.', item: '삼위일체와 판금 장화를 추천해요. 삼위일체로 공격력과 체력을 챙기고 판금 장화의 효과로 트런들의 기본 공격 피해를 줄이세요.', spell: '점멸과 점화를 추천해요. 트런들은 (P)\'헌납\'과 (W)\'얼음 왕국\'으로 회복력이 좋으니 점화의 치유 감소 효과로 억제하세요.' },
    '트린다미어': { lv1: '트린다미어는 (P)\'격노\'로 치명타 확률을 높이고 (Q)\'피의 갈망\'으로 체력을 회복하며 압박해요. 첫 웨이브는 무리하게 교환하지 말고 (W)\'무기 강화\'를 섞은 짧은 평타 딜교환 후 빠르게 빠지세요. (E)\'회전 베기\'로 거리를 좁히며 들어오는 타이밍에 맞춰 거리 조절을 하세요.', lv3: '(E)\'회전 베기\'와 평타 공격이 주력인 트린다미어에게 (E)\'반격\'은 매우 효과적이에요. (W)\'조롱의 외침\'에 걸려 공격력이 낮아진 상태에서는 무리하게 싸우지 말고 (E)\'반격\'으로 상대의 공격을 모두 회피한 뒤 기절시키세요. 기절시킨 직후 (Q)\'도약 공격\'과 (W)\'무기 강화\'를 연계해 빠르게 피해를 입히세요.', lv6: '(R)\'불사의 분노\'가 켜진 동안은 죽지 않으니 (R)\'무기의 달인\'으로 방어력과 마법 저항력을 높여 버티세요. (R)\'불사의 분노\' 지속시간이 끝나는 순간을 노려 (E)\'반격\'의 기절과 함께 강력한 피해를 입혀 마무리하세요. 라인을 포탑 쪽으로 당겨 트린다미어가 (E)\'회전 베기\'로 진입하도록 유도하고 정글의 도움을 받으세요.', item: '판금 장화와 삼위일체를 추천해요. 판금 장화는 트린다미어의 기본 공격 피해를 줄여주고 삼위일체는 체력과 공격 속도를 제공해 지속 싸움에서 앞서게 해요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 트린다미어의 (Q)\'피의 갈망\' 회복량을 줄여 킬각을 잡기 편해요.' },
    '티모': { lv1: '티모는 (E)\'맹독 다트\'를 묻히며 기본 공격으로 지속적인 피해를 입히니 거리를 조절하며 버티세요. (Q)\'도약 공격\'을 무작정 쓰기보다 미니언을 챙기며 티모의 체력을 관리하는 게 중요해요. 티모가 (P)\'유격 전투\'로 수풀에 숨어 기습할 수 있으니 시야 확보를 잊지 마세요.', lv3: '티모의 (Q)\'실명 다트\'에 맞으면 평타가 막히니 다트가 날아오는 길목을 피하세요. (E)\'반격\'은 평타만 피하고 다트는 막지 못하니, (Q)\'실명 다트\'가 빠진 뒤에 (Q)\'도약 공격\'으로 붙어 (W)\'무기 강화\'를 섞어 교환하고 빠지세요. 티모가 (W)\'신속한 이동\'으로 거리를 벌려도 (Q)\'도약 공격\'으로 따라붙으세요.', lv6: '티모가 깔아둔 (R)\'유독성 함정\'은 밟으면 둔화와 피해를 주니 버섯의 위치를 잘 파악하며 라인을 관리하세요. (R)\'무기의 달인\'을 켜서 마법 저항력을 높이고 (Q)\'도약 공격\'으로 티모에게 붙으면 처치할 기회를 만들 수 있어요. 티모의 (Q)\'실명 다트\'가 빠진 타이밍에 (E)\'반격\'과 함께 진입하여 빠르게 제압하세요.', item: '첫 코어로 삼위일체를 올려 전투력을 높이세요. 신발은 티모의 마법 피해를 견디기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 티모가 (W)\'신속한 이동\'으로 도망치려 할 때 점화로 체력을 깎아 마무리하기 좋아요.' },
    '판테온': { lv1: '판테온은 (Q)\'혜성의 창\'을 던져 견제하며 (P)\'필멸자의 의지\'가 쌓인 강화 스킬로 압박해요. (Q)\'혜성의 창\' 사거리 밖에서 대기하다가 스킬이 빠진 틈에 평타를 섞으며 (W)\'무기 강화\'로 짧게 딜교환하세요. 강화된 스킬이 들어올 때는 뒤로 물러나 체력 소모를 최소화하며 받아내세요.', lv3: '(W)\'방호의 도약\'으로 들어오는 순간 (E)\'반격\'을 켜서 상대의 기본 공격을 회피하고 기절시키세요. 판테온이 (E)\'방패 돌격\'을 사용하면 정면 공격이 무효화되니, 스킬이 끝날 때까지 기다렸다가 (Q)\'도약 공격\'으로 들어가세요. (W)\'방호의 도약\'이 빠진 상태에서는 (W)\'무기 강화\'를 섞은 평타 공격으로 빠르게 체력을 깎을 수 있어요.', lv6: '(R)\'거대 유성\'이 떨어지는 위치에서 빠르게 벗어나야 하며, 판테온이 착지한 직후 (R)\'무기의 달인\'을 사용해 방어력과 마법 저항력을 높이세요. (E)\'방패 돌격\'이 끝난 타이밍에 (Q)\'도약 공격\'으로 진입해 기절을 넣으면 확실하게 킬각을 잡을 수 있어요. 판테온이 (R)\'거대 유성\'으로 로밍을 갈 수 있으니 라인을 관리하며 정글러의 도움을 받으세요.', item: '삼위일체를 첫 코어로 선택해 공격 속도와 체력을 챙기고 강력한 피해를 입히세요. 신발은 판테온의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 라인 유지력을 높이고 빠른 합류를 통해 운영하며 판테온의 압박을 이겨내세요.' },
    '피들스틱': { lv1: '1~2레벨에는 (E)\'수확\'의 둔화와 침묵을 조심하며 거리 조절을 해요. 미니언을 통해 (Q)\'도약 공격\' 각을 보되, 무리하게 진입했다가 체력을 잃지 않도록 주의하세요. 상대의 (W)\'풍작\' 범위 밖에서 대기하며 천천히 파밍해요.', lv3: '(Q)\'도약 공격\'으로 빠르게 접근한 뒤 (E)\'반격\'을 사용해 상대의 움직임을 제한하고 기절을 노리세요. (E)\'수확\'의 중심부에서 침묵에 걸리지 않도록 주의하며 (W)\'무기 강화\'를 섞어 짧은 딜교환을 해요. 상대의 (W)\'풍작\' 시전 시 빠르게 공격해 스킬을 끊어주는 것이 중요해요.', lv6: '(R)\'까마귀 폭풍\'을 통한 기습 공격에 대비해 시야 확보에 신경 쓰고 (R)\'무기의 달인\'으로 마법 저항력을 높여 버티세요. (Q)\'공포\'에 걸려 도망칠 때는 당황하지 말고 거리 조절 후 다시 진입해요. 정글 개입 시 (E)\'반격\'의 기절로 아군을 보호하며 싸우세요.', item: '헤르메스의 발걸음과 삼위일체를 추천해요. 헤르메스의 발걸음은 강인함으로 공포와 침묵 지속시간을 줄여주고, 삼위일체는 공격력과 체력을 높여줘요.', spell: '점멸과 정화를 추천해요. 정화는 (Q)\'공포\'나 (E)\'수확\'의 침묵 효과를 즉시 제거해 빠르게 대응할 수 있게 해줘요.' },
    '피오라': { lv1: '피오라가 (Q)\'찌르기\'로 거리를 좁히며 (P)\'치명적인 검무\'의 급소를 노리면 체력을 회복하기 쉬워요. (Q)\'도약 공격\'을 사용하여 짧게 딜교환을 시도하되 급소 방향을 피해 움직이세요. 피오라의 (Q)\'찌르기\'가 빠진 틈에 교환을 시작해 급소를 맞는 횟수를 줄이세요.', lv3: '피오라의 (W)\'응수\'는 잠시 동안 모든 공격과 이동 불가 효과를 막아내니 이때는 (E)\'반격\'의 기절도 통하지 않아요. (W)\'응수\'가 켜진 동안은 기절을 아끼고 끝난 직후에 (Q)\'도약 공격\'으로 압박하세요. 피오라의 평타는 (E)\'반격\'으로 피하며 딜교환하세요.', lv6: '피오라가 (R)\'대결투\'를 사용하면 급소 네 군데가 드러나며 체력을 회복하니 급소 위치를 계속 바꿔주세요. (R)\'무기의 달인\'을 사용하여 방어력과 마법 저항력을 높여 피오라의 공격을 견뎌내야 해요. 피오라가 급소를 모두 가격하기 전에 (Q)\'도약 공격\'으로 거리를 벌리거나 싸움을 마무리하세요.', item: '첫 코어로 삼위일체를 구매하여 전투 지속력을 높이세요. 신발은 피오라의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 피오라의 (P)\'치명적인 검무\'를 통한 체력 회복을 줄이세요.' },
    '하이머딩거': { lv1: '하이머딩거는 (Q)\'H-28 G 진화형 포탑\'을 깔아 라인을 장악하니 포탑 사거리 밖에서 미니언을 챙기세요. (Q)\'도약 공격\'으로 무리하게 들어가기보다 포탑의 화력을 견디며 (W)\'마법공학 초소형 로켓\'의 견제를 피하며 파밍에 집중하세요.', lv3: '하이머딩거의 (E)\'CH-2 전자폭풍 수류탄\'이 빗나가면 (Q)\'도약 공격\'으로 빠르게 붙으세요. (E)\'반격\'을 사용해 포탑의 기본 공격을 회피하며 하이머딩거 본체까지 접근하는 것이 중요해요. (W)\'무기 강화\'를 섞어 짧고 강력하게 딜교환을 하고 빠지세요.', lv6: '하이머딩거가 (R)\'업그레이드!!!\'를 사용해 강화된 스킬을 쓰려고 하면 먼저 진입하지 마세요. (R)\'무기의 달인\'으로 마법 저항력을 높인 상태에서 (Q)\'도약 공격\'으로 진입해 포탑을 먼저 파괴하세요. 포탑이 정리되면 (E)\'반격\'을 활용해 하이머딩거를 압박하며 전투를 이끄세요.', item: '삼위일체와 헤르메스의 발걸음을 선택하세요. 삼위일체는 공격력과 공격 속도를 제공하며 헤르메스의 발걸음은 마법 저항력과 강인함을 제공해요.', spell: '점멸과 점화를 추천해요. (Q)\'도약 공격\'으로 진입한 뒤 점화로 마무리 피해를 입히며 승리하세요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_jax);
if (typeof module !== 'undefined') module.exports = top_jax;
